'use strict';
const $=s=>document.querySelector(s),app=$('#app'),KEY='world-master:v1',REGIONS=['アジア','ヨーロッパ','アフリカ','南北アメリカ','オセアニア'];let data=[],geo,terrain=[],heritage=[],session=null,view='home',storageOK=true;
let db={version:1,records:{},history:[]};try{const x=JSON.parse(localStorage.getItem(KEY));if(validBackup(x,false))db=x}catch(e){storageOK=false}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFKC').toLowerCase().replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-96)).replace(/[\s・･.．]/g,'').trim();
const accepted=(c,a)=>c.aliases.some(v=>norm(v)===norm(a));const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const flag=c=>`<span class="flagFrame"><img class="flag" src="${flagPath(c.id)}" alt="${c.scope==='un'?'国旗':'旗'}"></span>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){storageOK=false;showModal('<h2>記録を保存できませんでした</h2><p>この画面の記録・設定からバックアップを書き出してください。</p>')}}
function showModal(s,actions=''){$('#modalBody').innerHTML=s;$('#modalActions').innerHTML=actions;if(!$('#modal').open)$('#modal').showModal()}
function record(c,m){return db.records[c.id+':'+m]||{right:0,wrong:0,dates:[],last:0,streak:0}}
function totals(){const rs=Object.values(db.records);const n=rs.reduce((a,r)=>a+r.right+r.wrong,0),right=rs.reduce((a,r)=>a+r.right,0);return{n,p:n?Math.round(right/n*100):0,master:rs.flatMap(r=>Object.values(r.channels||{})).filter(r=>r.dates.length>=3&&r.streak>=3).length}}
function home(){view='home';session=null;const t=totals();app.innerHTML=`<section class="hero"><div><div class="eyebrow">LEARN · DISCOVER · MASTER</div><h1>地図の向こうに、<br>まだ知らない世界。</h1><p>旗と国、自然の形、世界の宝。<br>見て、探して、名前を答えよう。</p><button class="primary" onclick="setup('flag')">おすすめの10問から始める →</button><p class="note">${data.filter(c=>c.scope==='un').length}か国 ＋ ${data.filter(c=>c.scope!=='un').length}の国・地域<br>${terrain.length}の地形 ＋ ${heritage.length}件の世界遺産</p></div><div class="heroMap" id="heroMap"></div></section><div class="section"><span class="eyebrow">CHOOSE YOUR JOURNEY</span><h2>今日は、どこを学ぶ？</h2></div><div class="cards"><button class="card action" onclick="setup('flag')"><span class="tag">COUNTRIES & FLAGS ↗</span><b>国・国旗マスター</b><p>旗と名前、地図の位置をつなげよう</p></button><button class="card action terrainCard" onclick="terrainSetup()"><span class="tag">LANDSCAPES ↗</span><b>世界の地形マスター</b><p>山・山脈・川・湖・島・諸島・半島</p></button><button class="card action heritageCard" onclick="heritageSetup()"><span class="tag">WORLD HERITAGE ↗</span><b>世界遺産マスター</b><p>実際の写真から、文化と自然の宝を学ぼう</p></button></div><section class="challengeBanner section"><div><span class="eyebrow">WORLD TOUR CHALLENGE</span><h2>知っている世界を、ひとつに。</h2><p>国・国旗・地形・世界遺産を組み合わせて挑戦。<br>結果画像で、今日の発見を残そう。</p></div><button class="primary" onclick="mixedSetup()">総合チャレンジ →</button></section><div class="section stats"><div class="card stat"><strong>${t.n}</strong><span>これまでの回答</span></div><div class="card stat"><strong>${t.p}%</strong><span>正答率</span></div><div class="card stat"><strong>${t.master}</strong><span>別の3日で正解した学習項目</span></div></div><div class="section"><h2>しらべる・ふりかえる</h2><div class="row"><button onclick="explore()">国の地図図鑑</button><button onclick="terrainAtlas()">地形図鑑</button><button onclick="heritageAtlas()">世界遺産図鑑</button><button onclick="compareFlags()">似た旗の比較</button></div><div class="row section"><button onclick="setup('flag',true)">国・国旗の復習</button><button onclick="terrainSetup(true)">地形の復習</button><button onclick="heritageSetup(true)">世界遺産の復習</button><button onclick="mastery()">国の習熟度</button><button onclick="settings()">記録・バックアップ</button></div></div><p class="note">世界遺産と地形は代表例を収録しています。写真の出典と地図の精度は図鑑で確認できます。</p>${!storageOK?'<p class="notice">この環境では自動保存が利用できない可能性があります。記録を書き出して保管してください。</p>':''}`;mountMap($('#heroMap'),{decor:true})}
const modeLabel={flag:'国旗から国名',name:'地図から国名',location:'国名から位置'};
function setup(mode='flag',review=false){view='setup';app.innerHTML=`<div class="setup"><button class="back" onclick="home()">← ホーム</button><div class="eyebrow">${review?'REVIEW':'START YOUR JOURNEY'}</div><h1>${review?'苦手を、得意に。':'旅の準備をしよう。'}</h1><form id="setup" class="card"><div class="fields"><div><label for="mode">学び方</label><select id="mode">${Object.entries(modeLabel).map(([v,n])=>`<option value="${v}" ${v===mode?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="region">地域</label><select id="region"><option>世界全体</option>${REGIONS.map(r=>`<option>${r}</option>`).join('')}</select></div><div><label for="level">難易度</label><select id="level"><option value="intro">入門・代表的な国</option><option value="all">基本・選んだ範囲をすべて</option></select></div><div><label for="input">回答方法（国名問題）</label><select id="input"><option value="text">キーボード入力</option><option value="choice">4択</option><option value="ink">手書き・かな（ベータ）</option></select></div><div><label for="scope">出題範囲</label><select id="scope">${scopeOptions()}</select></div><div><label for="count">問題数</label><select id="count"><option>10</option><option>5</option><option>20</option><option>30</option></select></div><div><label for="practice">プレイ形式</label><select id="practice"><option value="practice">練習・ヒントあり</option><option value="test">テスト・ヒントなし</option></select></div></div><p class="note">追加範囲は代表例を収録しています。分類は一律ではありません。<button type="button" class="textButton" onclick="scopeInfo()">範囲の説明</button><br>手書きは1文字ずつ、ひらがな・カタカナで入力します。認識ミスは修正してから回答できます。復習は回答方法ごとに選びます。</p><button class="primary" type="submit">${review?'復習':'学習'}をはじめる →</button><p id="setupMsg" aria-live="polite"></p></form></div>`;$('#setup').onsubmit=e=>{e.preventDefault();start({mode:$('#mode').value,region:$('#region').value,level:$('#level').value,input:$('#input').value,scope:$('#scope').value,count:+$('#count').value,practice:$('#practice').value,review})};$('#scope').onchange=()=>{if($('#scope').value!=='basic')$('#level').value='all'};if(session?.cfg.mode===mode){const prev=session.cfg;for(const k of ['scope','region','level','input','count','practice'])if(prev[k]!==undefined&&[...$('#'+k).options].some(o=>o.value===String(prev[k])))$('#'+k).value=String(prev[k])}}
const intro='JP US GB FR DE IT ES CN KR IN AU BR CA EG ZA KE CH GR TR TH VN ID NZ RU MX AR SA SE NO FI'.split(' ');
function start(cfg){cfg.count=Math.max(1,Math.min(data.length,Math.floor(+cfg.count)||10));let pool=data.filter(c=>inScope(c,cfg.scope||'basic')&&(!cfg.ids||cfg.ids.includes(c.id))&&(cfg.region==='世界全体'||c.region===cfg.region)&&(cfg.level==='all'||intro.includes(c.id)));if(cfg.review){pool=pool.filter(c=>{let r=channelRecord(c,cfg.mode,cfg.input);return r.wrong&&(!r.lastRight||Date.now()-r.last>7*86400000)});if(!pool.length){$('#setupMsg').textContent='この条件の復習問題はありません。地域や難易度、学び方を変えてみましょう。';return}pool=shuffle(pool).sort((a,b)=>channelRecord(a,cfg.mode,cfg.input).last-channelRecord(b,cfg.mode,cfg.input).last)}else pool=shuffle(pool);if(!pool.length){$('#setupMsg').textContent='この条件では出題できません。';return}session={cfg,queue:pool.slice(0,cfg.count),i:0,results:[],began:Date.now(),selected:null,done:false,hint:0};question()}
let mapAPI=null;
function question(){if(session?.mixed){Object.assign(session.cfg,session.queue[session.i].task)}if(session?.cfg.content==='heritage')return heritageQuestion();if(session?.cfg.content==='terrain')return terrainQuestion();view='game';const s=session,c=s.queue[s.i],m=s.cfg.mode;s.done=false;s.selected=null;s.hint=0;const title=m==='flag'?'この旗は、どこの国・地域？':m==='name'?'色のついた国・地域の名前は？':`${c.name}は、どこにある？`;app.innerHTML=`<button class="back" onclick="leave()">← 学習を終了</button><div class="row between"><span class="eyebrow">${modeLabel[m]} · ${s.cfg.practice==='test'?'テスト':'練習'}</span><b>${s.i+1} / ${s.queue.length} 問</b></div><div class="progress"><i style="width:${s.i/s.queue.length*100}%"></i></div><div class="gameLayout"><div id="questionMap" ${m==='flag'?'hidden':''}></div><section class="card answerPanel" ${m==='flag'?'style="grid-column:1/-1;max-width:700px;width:100%;margin:auto"':''}><h2>${m==='location'?nameMarkup(c)+'は、どこにある？':esc(title)}</h2>${m==='flag'?flag(c):''}${m==='flag'&&['ID','MC','RO','TD'].includes(c.id)?`<p class="notice">この問題の地域：${c.region}<br><span class="note">図案が非常に似ている旗のため、地域も手がかりにしてください。</span></p>`:''}<div id="answerArea">${m==='location'?'<p class="muted">地図を拡大して国を選び、「回答する」で確定。</p><p id="selection" aria-live="polite">まだ選ばれていません</p>':s.cfg.input==='ink'?'<div id="inkArea"></div>':s.cfg.input==='text'?'<form id="answerForm"><label for="answer">国の名前</label><input id="answer" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="ひらがな・カタカナ・漢字・英語"><p class="note">漢字の国名は読み方でも答えられます。</p><button class="primary" type="submit">回答する</button></form>':'<div class="choices" id="choices"></div>'}${m==='location'?'<button id="submitLocation" class="primary" disabled onclick="submitAnswer()">回答する</button>':''}<div class="row section">${s.cfg.practice==='practice'?'<button onclick="hint()">ヒント</button>':''}<button onclick="submitAnswer(true)">わからない</button></div><p id="hint" class="note" aria-live="polite"></p></div><div id="feedback" aria-live="polite"></div></section></div>`;
 if(m!=='flag')mapAPI=mountMap($('#questionMap'),{target:m==='name'?c:null,focusTarget:m==='name',onSelect:code=>{if(s.done||m!=='location')return;s.selected=code;mapAPI.select(code);$('#selection').textContent='国を選びました。回答を確定してください。';$('#submitLocation').disabled=false}});
 if(m!=='location'&&s.cfg.input==='text'){$('#answerForm').onsubmit=e=>{e.preventDefault();submitAnswer()};$('#answer').onkeydown=e=>{if(e.key==='Enter'&&(e.isComposing||e.keyCode===229)){e.preventDefault();e.stopPropagation()}}}
 if(m!=='location'&&s.cfg.input==='ink')mountHandwriting();
 if(m!=='location'&&s.cfg.input==='choice'){const choices=answerChoices(c,s.cfg);s.options=choices;$('#choices').innerHTML=choices.map(x=>`<button data-id="${x.id}">${esc(x.name)}</button>`).join('');$('#choices').onclick=e=>{const b=e.target.closest('button');if(b)submitAnswer(false,b.dataset.id)}}
}
function hint(){if(session?.cfg.content==='heritage')return heritageHint();if(session?.cfg.content==='terrain')return terrainHint();const s=session,c=s.queue[s.i];s.hint++;$('#hint').textContent=s.hint===1?`地域：${c.region}`:`名前の最初：${c.name.slice(0,1)}　／　${c.name.length}文字`;if(s.cfg.mode==='location'&&s.hint>1)mapAPI.focus(c)}
function submitAnswer(skip=false,choice=null){if(session?.cfg.content==='heritage')return heritageAnswer(skip,choice);if(session?.cfg.content==='terrain')return terrainAnswer(skip,choice);const s=session;if(!s||s.done)return;const c=s.queue[s.i],m=s.cfg.mode;let a=skip?'':m==='location'?s.selected:choice||$('#inkText')?.value||$('#answer')?.value||'';if(!skip&&!String(a).trim()){if($('#answer'))$('#answer').focus();return}const ok=!skip&&(m==='location'||choice?a===c.id:accepted(c,a));s.done=true;const r=record(c,m),today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Tokyo'});r[ok?'right':'wrong']++;r.last=Date.now();r.lastRight=ok;r.streak=ok&&!s.hint?r.streak+1:0;if(ok&&!s.hint&&!r.dates.includes(today))r.dates.push(today);r.hinted=(r.hinted||0)+(s.hint?1:0);updateChannel(r,s.cfg,m,ok,s.hint,today);db.records[c.id+':'+m]=r;s.results.push({id:c.id,ok,hint:s.hint,answer:a,input:channelKey(m,s.cfg.input),mode:m,content:s.cfg.content||'country'});save();$('#answerArea').hidden=true;$('#feedback').innerHTML=`<div class="${ok?'good':'bad'}"><b>${ok?'正解！':'ここで覚えよう'}</b><div class="feedbackName">${esc(c.name)}</div><p>${esc(c.en)}<br>${esc(c.region)}</p>${c.scope!=='un'?`<p class="note">${esc(c.status)}</p>`:''}${comparisonFor(c)?`<button onclick="compareFlags('${c.id}')">似ている旗との違いを見る</button>`:''}${m!=='flag'?flag(c):''}<p class="note">${s.hint?'ヒントを使って正解した記録は、別日習得の回数には含みません。':'地図で位置も確認してみよう。'}</p><button class="primary" onclick="next()">${s.i+1===s.queue.length?'結果を見る':'次の問題へ'} →</button></div>${m==='flag'?'<div id="feedbackMap" class="section"></div>':''}`;if(m==='flag')mountMap($('#feedbackMap'),{target:c});else mapAPI.reveal(c,s.selected);}
function next(){if(!session?.done||session.ended)return;if(++session.i<session.queue.length)question();else{session.ended=true;result()}}
function result(){if(session?.mixed)return mixedResult();if(session?.cfg.content==='heritage')return heritageResult();if(session?.cfg.content==='terrain')return terrainResult();view='result';const s=session,n=s.results.length,right=s.results.filter(x=>x.ok).length;db.history.unshift({at:Date.now(),mode:s.cfg.mode,region:s.cfg.region,input:new Set(s.results.map(r=>r.input)).size>1?'mixed':s.cfg.input,scope:s.cfg.scope||'basic',practice:s.cfg.practice,right,n});db.history=db.history.slice(0,100);save();app.innerHTML=`<div class="setup"><div class="eyebrow">JOURNEY COMPLETE</div><h1>世界が、少し近くなった。</h1><section class="card"><div class="resultScore">${right}<span style="font-size:24px"> / ${n}</span></div><p>${right===n?'全問正解！別の日にも挑戦して覚えよう。':'間違えた場所は、次の発見への入り口。'}</p><div class="row"><button class="primary" onclick="setup('${s.cfg.mode}',true)">苦手を復習</button><button onclick="setup('${s.cfg.mode}')">もう一度挑戦</button><button onclick="home()">ホーム</button><button onclick="showResultCard()">結果画像をつくる</button></div></section><div class="section list">${s.results.map(x=>{const c=data.find(c=>c.id===x.id);return`<button class="countryRow" onclick="country('${c.id}')"><img class="miniFlag" src="${flagPath(c.id)}" alt=""><span>${x.ok?'○':'×'} ${esc(c.name)}<small>${x.hint?'ヒント使用':'ヒントなし'}</small></span></button>`}).join('')}</div></div>`}
function leave(){showModal('<h2>学習を終了しますか？</h2><p>ここまでに回答した記録は保存されています。</p>','<button id="leaveHome" class="primary" type="button">ホームに戻る</button>');$('#leaveHome').onclick=()=>{$('#modal').close();home()}}
function explore(){view='explore';app.innerHTML=`<button class="back" onclick="home()">← ホーム</button><div class="eyebrow">WORLD ATLAS</div><h1>気になる国を、見つけよう。</h1><p class="muted">地図や一覧から選ぼう。追加の国・地域は範囲を切り替えて調べられます。</p><div id="atlas"></div><div class="fields"><div><label for="search">名前で検索</label><input id="search" placeholder="日本 / にほん / Japan"></div><div><label for="atlasScope">収録範囲</label><select id="atlasScope">${scopeOptions()}</select></div></div><p id="atlasCount" class="note"></p><div id="countryList" class="list section"></div>`;mapAPI=mountMap($('#atlas'),{onSelect:country});$('#search').oninput=()=>renderList($('#search').value);$('#atlasScope').onchange=()=>renderList($('#search').value);renderList('')}
function renderList(q){const found=data.filter(c=>inScope(c,$('#atlasScope')?.value||'basic')&&c.aliases.some(a=>norm(a).includes(norm(q)))).sort((a,b)=>a.name.localeCompare(b.name,'ja'));$('#atlasCount').textContent=`${found.length}項目`;$('#countryList').innerHTML=found.map(c=>`<button class="countryRow" onclick="country('${c.id}')"><img class="miniFlag" src="${flagPath(c.id)}" alt=""><span>${esc(c.name)}<small>${c.region} · ${typeLabel(c)}</small><small>${countryProgress(c)}</small></span></button>`).join('')||'<p>見つかりませんでした。</p>'}
function country(id){const c=data.find(c=>c.id===id);if(!c)return;showModal(`<div class="eyebrow">WORLD ATLAS · ${c.region}</div><h2>${nameMarkup(c)}</h2>${flag(c)}<p>${esc(c.en)} · ${typeLabel(c)}</p><div class="notice">${esc(c.status)}<br><span class="note">確認日：${c.checked} · ${c.flagKind}</span></div><div id="detailMap" class="section"></div><p class="note">位置の目安：${c.lat>=0?'北緯':'南緯'} ${Math.abs(c.lat).toFixed(1)}° ／ ${c.lng>=0?'東経':'西経'} ${Math.abs(c.lng).toFixed(1)}°</p><div class="skillGrid">${Object.entries(modeLabel).map(([m,n])=>{const r=record(c,m);return`<div class="skill"><b>${n}</b><p>${r.right}正解 / ${r.wrong}不正解</p>${skillDetails(r,m)}</div>`}).join('')}</div><div class="row section">${comparisonFor(c)?`<button onclick="compareFlags('${c.id}')">似た旗を比較</button>`:''}<button class="primary" onclick="document.querySelector('#modal').close();practiceCountry('${c.id}')">この項目を練習</button></div><details><summary>出典と分類</summary><p class="note">${c.sources.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title)}</a>`).join('<br>')}<br>境界表示は実効支配を基にした地図データの表現です。国家としての承認を表すものではありません。</p></details>`);const mp=mountMap($('#detailMap'),{target:c});if(c.scope!=='un')mp.focus(c)}
function settings(){const t=totals();showModal(`<h2>記録・バックアップ</h2><p>${t.n}問回答 · 正答率${t.p}%</p><p class="note">この端末のブラウザに保存しています。端末間では自動同期しません。</p><div class="row"><button onclick="exportData()">記録を書き出す</button><label><input type="file" accept="application/json" onchange="importData(this.files[0])">記録を読み込む</label></div><h3 class="section">最近の学習</h3><div class="scrollList">${db.history.slice(0,20).map(h=>`<p>${new Date(h.at).toLocaleDateString('ja-JP')} · ${({terrainName:'地形・名前',terrainLocation:'地形・位置',heritagePhoto:'世界遺産・写真',heritageMap:'世界遺産・地図',heritageLocation:'世界遺産・位置',heritageCountry:'世界遺産・国',heritageType:'世界遺産・分類',mixed:'総合チャレンジ'}[h.mode]||allLabels()[h.mode])} · ${h.right}/${h.n}<br><span class="note">${h.dataVersion!==DATA_VERSION?'旧条件 / ':''}${h.level?esc(LEVELS[h.level]||h.level)+' / ':''}${esc(h.region)} / ${inputLabel(h.mode,h.input)} / ${h.content==='heritage'?'世界遺産':h.content==='mixed'?'総合チャレンジ':h.content==='terrain'?'世界の地形':scopeLabel[h.scope||'basic']||'基本'} / ${h.practice==='test'?'テスト':'練習'}</span></p>`).join('')||'<p>まだ記録がありません。</p>'}</div><button onclick="resetConfirm()">学習記録を削除する</button>`)}
function exportData(){const b=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='world-master-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importData(f){if(!f)return;try{const x=JSON.parse(await f.text());if(!validBackup(x,true))throw Error();showModal('<h2>記録を読み込みますか？</h2><p>現在の記録を、選んだバックアップで置き換えます。</p><button id="confirmImport" class="primary">読み込む</button>');$('#confirmImport').onclick=()=>{db=x;save();$('#modal').close();home()}}catch(e){showModal('<h2>読み込めませんでした</h2><p>世界マスターの有効なバックアップを選んでください。</p>')}}
function resetConfirm(){showModal('<h2>学習記録を削除しますか？</h2><p>この操作は元に戻せません。必要なら先にバックアップを書き出してください。</p><button onclick="db={version:1,records:{},history:[]};save();document.querySelector(\'#modal\').close();home()">削除を確定する</button>')}
function sources(){showModal(`<h2>データと使い方</h2><p>結果画像用フォント：Noto Sans JPを文字抽出・名称変更したWorldMasterShare（<a href="licenses/NotoSansJP-OFL.txt">SIL Open Font License 1.1</a>）。</p><p>第4段階：世界遺産・総合チャレンジ・結果画像に対応しています。<button onclick="heritageSources()">世界遺産と写真の出典</button></p><p>地形：Natural Earth 1:10m地形ラベル・山頂、1:50m河川・湖。山脈・島々・半島は学習用の範囲で、厳密な地形境界・海岸線ではありません。川は主な流路を示し、上流部・河口の分流・支流を省略する場合があります。イベリア半島はスペイン・ポルトガル本土の地図形状から近似しています。<button onclick="terrainSources()">地形の出典と精度</button></p><p>国連加盟国 ${data.filter(c=>c.scope==='un').length}か国と、追加の ${data.filter(c=>c.scope!=='un').length}の国・地域と、${terrain.length}の地形を学べます。確認日：2026年10月16日。</p><p>地図：<a href="https://www.naturalearthdata.com/" target="_blank" rel="noopener">Natural Earth</a> 1:50m（パブリックドメイン）。正距円筒図法で表示しています。面積や形にゆがみがあり、極地ほど目立ちます。</p><p>国境はNatural Earthの実効支配に基づく表現です。係争地域を含む境界の表示は、特定の主張への支持を意味しません。追加範囲は代表例です。世界中のすべての地域を網羅したものではありません。</p><p>国の範囲：<a href="https://www.un.org/en/about-us/member-states" target="_blank" rel="noopener">国連加盟国一覧</a>。地図の細部は簡略化されています。小国の丸印は選択のための補助表示で、領土の面積を表しません。</p><p>国旗：<a href="licenses/flag-native-NOTICE.md">元の比率を保つSVG・出典とライセンス</a>。旧flag-icons画像も互換用に保持しています。</p><p>漢字・かな・英語と登録済みの別名を受け付けます。似ているだけの別名は自動で正解にしません。</p><p>かな認識は177文字のひらがな・カタカナ・長音に対応する端末内テンプレート照合です（ベータ）。漢字は入力欄で「漢字（ベータ）」を選ぶと別エンジンで認識します。英字は対象外です。書き順や画数によって精度が下がるため、候補の確認・修正ができます。筆跡の外部送信・追加料金はありません。認識モデルの初回読み込みには通信が必要です。<br>モデル：Ulrich Apel and the KanjiVG contributors, <a href="https://kanjivg.tagaini.net/">KanjiVG</a>。かなを抽出し、各画を16点に標本化・正規化しています。<a href="https://creativecommons.org/licenses/by-sa/3.0/">CC BY-SA 3.0</a> · <a href="licenses/KanjiVG-CC-BY-SA-3.0.txt">ライセンス</a>。<br>北キプロスの旗：<a href="https://commons.wikimedia.org/wiki/File:Flag_of_the_Turkish_Republic_of_Northern_Cyprus.svg">Wikimedia Commons / Mike Rohsopht 他、ファイル履歴参照</a>（未改変、単純図形としてパブリックドメインの表示あり）。</p>`)}
function mountMap(host,opt={}){const NS='http://www.w3.org/2000/svg',make=(tag,attrs)=>{let el=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))el.setAttribute(k,v);return el};host.innerHTML='<div class="mapbox"><div class="mapTools"><button aria-label="拡大">＋</button><button aria-label="縮小">−</button><button>全体</button></div><svg class="mapSvg" role="group" aria-label="世界地図"></svg><div class="mapCaption">Natural Earth · 小国の丸は選択用の目印</div></div>';const svg=host.querySelector('svg'),g=make('g',{});svg.append(g);let vb=[0,0,720,340],selected=null;svg.setAttribute('viewBox',vb.join(' '));svg.style.background='#e7efea';const wrap=x=>opt.focusTarget&&opt.target?opt.target.lng+((x-opt.target.lng+540)%360)-180:x;const pos=([x,y])=>[(wrap(x)+180)*2,(85-y)*2];
 function ringPath(r){let out='',prev=null;for(const p of r){const [x,y]=pos(p);out+=(prev&&Math.abs(x-prev[0])<360?'L':'M')+x.toFixed(2)+','+y.toFixed(2);prev=[x,y]}return out+'Z'}
 for(const f of geo.features){const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[];const el=make('path',{d:polys.map(p=>p.map(ringPath).join('')).join(''),'data-code':f.properties.code,'fill-rule':'evenodd'});g.append(el)}
 // Markers keep islands and microstates reachable at every zoom level.
 const micro=new Set('AD AG BH BB CV KM DM GD KI LI MV MT MH MU FM MC NR PW KN LC VC WS SM ST SC SG TO TV'.split(' '));
 for(const c of data){if(!opt.terrain&&(micro.has(c.id)||c.scope!=='un')){const [x,y]=pos([c.lng,c.lat]);g.append(make('circle',{cx:x,cy:y,r:3.5,fill:'#7b9c80',stroke:'#fff','stroke-width':1,'data-code':c.id,'data-micro':'1'}))}}
 const nodes=code=>[...g.querySelectorAll('[data-code]')].filter(n=>n.dataset.code===code);
 function paint(){g.querySelectorAll('.target,.selected,.correct').forEach(n=>{n.classList.remove('target','selected','correct');if(n.tagName==='circle')n.setAttribute('fill','#7b9c80')});for(const [c,cl]of [[opt.target?.id,'target'],[selected,'selected']])if(c)nodes(c).forEach(n=>{n.classList.add(cl);if(n.tagName==='circle')n.setAttribute('fill',cl==='target'?'#eaa15d':'#176d60')})}
 function update(){svg.setAttribute('viewBox',vb.join(' '));g.querySelectorAll('circle').forEach(n=>n.setAttribute('r',Math.max(.08,3.5*vb[2]/720)));opt.onViewChange?.([...vb])}
 function focus(c){const [x,y]=pos([c.lng,c.lat]);vb=[x-70,y-55,140,110];update()}
 function zoom(k,anchor){const cx=anchor?.[0]??vb[0]+vb[2]/2,cy=anchor?.[1]??vb[1]+vb[3]/2;const w=Math.max(3,Math.min(1000,vb[2]*k)),ratio=w/vb[2];vb=[cx+(vb[0]-cx)*ratio,cy+(vb[1]-cy)*ratio,w,vb[3]*ratio];update()}
 const buttons=host.querySelectorAll('.mapTools button');buttons[0].onclick=()=>zoom(.65);buttons[1].onclick=()=>zoom(1.55);buttons[2].onclick=()=>{vb=[0,0,720,340];update()};
 let pointers=new Map(),down=null,moved=false,pinch=null;
 svg.onpointerdown=e=>{if(opt.decor)return;svg.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===1){down={x:e.clientX,y:e.clientY,v:[...vb],code:e.target.dataset.code,feature:e.target.dataset.terrain};moved=false}else if(pointers.size===2){moved=true;const p=[...pointers.values()];pinch={dist:Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]),v:[...vb]}}};
 svg.onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,[e.clientX,e.clientY]);const rect=svg.getBoundingClientRect();if(pointers.size===2&&pinch){const p=[...pointers.values()],dist=Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]);vb=[...pinch.v];zoom(pinch.dist/Math.max(1,dist));moved=true}else if(down&&pointers.size===1){const dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.hypot(dx,dy)>5)moved=true;if(moved){const scale=Math.max(down.v[2]/rect.width,down.v[3]/rect.height);vb=[down.v[0]-dx*scale,down.v[1]-dy*scale,down.v[2],down.v[3]];update()}}};
 function end(e,cancel=false){if(!pointers.has(e.pointerId))return;const code=down?.code;if(!cancel&&!moved&&pointers.size===1&&down?.feature)opt.onFeatureSelect?.(down.feature);if(!cancel&&!moved&&pointers.size===1&&code&&data.some(c=>c.id===code))opt.onSelect?.(code);pointers.delete(e.pointerId);if(!pointers.size){down=null;pinch=null}else{moved=true;down=null}}
 svg.onpointerup=e=>end(e);svg.onpointercancel=e=>end(e,true);svg.addEventListener('wheel',e=>{if(opt.decor)return;e.preventDefault();zoom(e.deltaY>0?1.15:.85)},{passive:false});paint();if(opt.target&&opt.target.scope!=='un')focus(opt.target);
 if(opt.decor){host.querySelector('.mapTools').hidden=true;host.querySelector('.mapCaption').hidden=true}
 const api={fit(bounds){const [x1,y1]=pos([bounds[0],bounds[3]]),[x2,y2]=pos([bounds[2],bounds[1]]);const w=Math.max(12,x2-x1)*1.4,h=Math.max(10,y2-y1)*1.4;vb=[(x1+x2-w)/2,(y1+y2-h)/2,w,h];update()},refresh:update,select(code){selected=code;paint()},focus,reveal(c,guess){opt.target=null;selected=guess;paint();nodes(c.id).forEach(n=>{n.classList.add('correct');if(n.tagName==='circle')n.setAttribute('fill','#176d60')});if(!guess)focus(c)}};
 if(opt.focusTarget&&opt.target){
  const q=opt.target,f=geo.features.find(f=>f.properties.code===q.id),polys=f?.geometry.type==='Polygon'?[f.geometry.coordinates]:f?.geometry.type==='MultiPolygon'?f.geometry.coordinates:[];
  const boxes=polys.map(p=>{const pts=p[0].map(([x,y])=>[wrap(x),y]);return[Math.min(...pts.map(p=>p[0])),Math.min(...pts.map(p=>p[1])),Math.max(...pts.map(p=>p[0])),Math.max(...pts.map(p=>p[1]))]}).filter(b=>b[2]-b[0]<355);
  const distance=b=>Math.hypot(Math.max(b[0]-q.lng,0,q.lng-b[2])*Math.cos(q.lat*Math.PI/180),Math.max(b[1]-q.lat,0,q.lat-b[3]));
  boxes.sort((a,b)=>distance(a)-distance(b)||((b[2]-b[0])*(b[3]-b[1])-(a[2]-a[0])*(a[3]-a[1])));
  const primary=boxes[0]||[q.lng-.5,q.lat-.5,q.lng+.5,q.lat+.5],width=Math.max(2,primary[2]-primary[0]),height=Math.max(2,primary[3]-primary[1]);
  const near=boxes.filter(b=>b[0]>=primary[0]-Math.max(6,width*.5)&&b[2]<=primary[2]+Math.max(6,width*.5)&&b[1]>=primary[1]-Math.max(6,height*.5)&&b[3]<=primary[3]+Math.max(6,height*.5));
  const bounds=near.length?[Math.min(...near.map(b=>b[0])),Math.min(...near.map(b=>b[1])),Math.max(...near.map(b=>b[2])),Math.max(...near.map(b=>b[3]))]:primary;
  const frame=()=>api.fit(bounds);frame();host.classList.add('countryQuestionMap');
  const caption=host.querySelector('.mapCaption');caption.textContent='太い枠の場所が出題対象です。丸は面積・形を表しません。'+(boxes.length>near.length?' 主な地域を拡大しています。離れた島・海外領土は全体表示で確認できます。':'');
  const back=document.createElement('button');back.type='button';back.textContent='対象へ';back.onclick=frame;host.querySelector('.mapTools').append(back);
  const [cx,cy]=pos([q.lng,q.lat]);if(!nodes(q.id).length)g.append(make('circle',{cx,cy,r:3.5,'data-code':q.id,'data-micro':'1',class:'target'}));
  buttons[2].onclick=()=>{vb=[(q.lng+180)*2-360,0,720,340];update()};
 }
 return api;
}
function validBackup(x,known=true){
 const safeCount=n=>Number.isSafeInteger(n)&&n>=0;
 const safeRec=r=>r&&typeof r==='object'&&!Array.isArray(r)&&['right','wrong','last','streak'].every(k=>safeCount(r[k]))&&Array.isArray(r.dates)&&r.dates.every(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d))&&(r.lastRight===undefined||typeof r.lastRight==='boolean')&&(r.hinted===undefined||safeCount(r.hinted));
 if(!x||x.version!==1||!x.records||typeof x.records!=='object'||Array.isArray(x.records)||!Array.isArray(x.history))return false;
 for(const [k,r] of Object.entries(x.records)){const m=k.match(/^([A-Z]{2,3}|terrain-(?:mountain|range|river|lake|island|archipelago|peninsula|sea|bay|strait|desert|plain|plateau)-\d{2}|cap-[a-z]{2}-[a-z0-9-]+|wh-\d+):(flag|name|location|terrainName|terrainLocation|heritagePhoto|heritageMap|heritageLocation|heritageCountry|heritageType|heritageClue|terrainClue|silhouette|rotated|chooseFlag|flagLocation|countryClue|capitalName|capitalCountry|capitalMap|capitalLocation|capitalFlag)$/);if(!m||!safeRec(r)||known&&!data.concat(terrain,heritage,capitals).some(c=>c.id===m[1]))return false;if(r.channels){if(typeof r.channels!=='object'||Array.isArray(r.channels))return false;for(const [key,ch]of Object.entries(r.channels))if(!['text','ink','choice','map'].includes(key)||!safeRec(ch))return false}if(r.legacy&&(!safeCount(r.legacy.right)||!safeCount(r.legacy.wrong)))return false}
 return x.history.every(h=>h&&safeCount(h.at)&&['flag','name','location','terrainName','terrainLocation','heritagePhoto','heritageMap','heritageLocation','heritageCountry','heritageType','heritageClue','terrainClue','silhouette','rotated','chooseFlag','flagLocation','countryClue','capitalName','capitalCountry','capitalMap','capitalLocation','capitalFlag','mixed'].includes(h.mode)&&['text','ink','choice','mixed'].includes(h.input)&&['practice','test'].includes(h.practice)&&['世界全体','アジア','ヨーロッパ','アフリカ','南北アメリカ','オセアニア'].includes(h.region)&&safeCount(h.right)&&safeCount(h.n)&&h.right<=h.n&&(h.scope===undefined||['basic','extended','limited','regions','all'].includes(h.scope)));
}

const scopeLabel={basic:'基本・国連加盟国',extended:'拡張・オブザーバーを含む',limited:'発展・承認が限定的な国・地域を含む',regions:'自治地域・自由連合を含む',all:'すべての収録対象'};
const scopeGroups={basic:['un'],extended:['un','observer'],limited:['un','observer','limited'],regions:['un','observer','territory','associated'],all:['un','observer','limited','territory','associated']};
function inScope(c,v){return(scopeGroups[v]||scopeGroups.basic).includes(c.scope||'un')}
function scopeOptions(){return Object.entries(scopeLabel).map(([v,n])=>`<option value="${v}">${n}（${data.filter(c=>inScope(c,v)).length}）</option>`).join('')}
function typeLabel(c){return{un:'国連加盟国',observer:c.id==='VA'?'聖座・バチカン':'国連オブザーバー',limited:'承認・位置付けが異なる地域',territory:'自治地域・海外領土など',associated:'自由連合関係'}[c.scope]||'国・地域'}
function scopeInfo(){showModal(`<h2>出題範囲について</h2><p>基本は国連加盟国のみ。追加範囲は自分で選んだときに出題されます。</p>${Object.entries(scopeLabel).map(([k,n])=>`<p><b>${n}：${data.filter(c=>inScope(c,k)).length}項目</b><br><span class="note">${{basic:'国連加盟国を対象にします。',extended:'パレスチナと、聖座に対応する地理対象のバチカンを追加します。',limited:'さらに台湾・コソボ・北キプロスを収録。一律に同じ承認状況とは扱いません。',regions:'香港・マカオ・グリーンランド・プエルトリコ・グアムと、自由連合関係にあるクック諸島・ニウエを追加します。',all:'上記の全収録対象です。世界中の国・地域の完全な一覧ではありません。'}[k]}</span></p>`).join('')}<p class="notice">国連での地位、他国による承認、実効統治は異なる概念です。それぞれの図鑑ページで位置付けと出典を確認できます。確認日：2026年10月16日。</p>`)}
function nameMarkup(c){return /[一-龯]/.test(c.name)&&c.reading&&c.reading!==c.name?`<ruby>${esc(c.name)}<rt>${esc(c.reading)}</rt></ruby>`:esc(c.name)}
const inputLabel=(m,i)=>m==='heritageCountry'?'選択問題（所在国・複数選択）':m==='heritageType'?'選択問題（遺産の種類）':(m==='location'||m==='terrainLocation'||m==='heritageLocation'||m==='capitalLocation'||m==='flagLocation')?'地図タップ':({text:'キーボード入力',ink:'手書き入力',choice:'4択',mixed:'入力方法の混在'}[i]||'旧版の合算');
function channelKey(m,i){return (m==='location'||m==='terrainLocation'||m==='heritageLocation'||m==='capitalLocation'||m==='flagLocation')?'map':(i||'text')}
function channelRecord(c,m,i){const r=record(c,m);return r.channels?.[channelKey(m,i)]||(r.channels?{right:0,wrong:0,dates:[],last:0,streak:0}:r)}
function updateChannel(r,cfg,m,ok,hints,today){const k=channelKey(m,cfg.input);if(!r.channels){r.channels={};r.legacy={right:r.right-(ok?1:0),wrong:r.wrong-(ok?0:1)}}const ch=r.channels[k]||{right:0,wrong:0,dates:[],last:0,streak:0,hinted:0};ch[ok?'right':'wrong']++;ch.last=Date.now();ch.lastRight=ok;ch.streak=ok&&!hints?ch.streak+1:0;ch.hinted+=hints?1:0;if(ok&&!hints&&!ch.dates.includes(today))ch.dates.push(today);r.channels[k]=ch}
function statusOf(r){if(!r||!r.right&&!r.wrong)return'未挑戦';if(r.dates.length>=3&&r.streak>=3)return'マスター';if(r.dates.length>=2&&r.streak>=2)return'覚えてきた';return'練習中'}
function skillDetails(r,m){const cs=Object.entries(r.channels||{});return cs.map(([k,v])=>`<div class="skillLine"><span>${inputLabel(m,k==='map'?'text':k)}</span><b class="badge">${statusOf(v)}</b><small>${v.right}正解 / ${v.wrong}不正解 · ヒントなし正解 ${v.dates.length}日</small></div>`).join('')+((r.legacy?.right||r.legacy?.wrong)||(!r.channels&&(r.right||r.wrong))?`<p class="note">旧版の合算記録も保存されています。入力方法別の記録は更新後の回答から集計します。</p>`:'')+(!cs.length&&!r.right&&!r.wrong?'<p class="note">まだ挑戦していません。</p>':'')}
function countryProgress(c){const rs=Object.keys(modeLabel).map(m=>record(c,m));let n=rs.reduce((a,r)=>a+r.right+r.wrong,0);return n?`${n}回学習 · ${rs.filter(r=>r.channels&&Object.values(r.channels).some(v=>statusOf(v)==='マスター')).length}分野をマスター`:'未挑戦'}
function practiceCountry(id){start({mode:'flag',region:'世界全体',level:'all',scope:'all',input:'text',count:1,practice:'practice',ids:[id],review:false})}
function mastery(){view='mastery';app.innerHTML=`<button class="back" onclick="home()">← ホーム</button><div class="eyebrow">YOUR PROGRESS</div><h1>覚えたことが、見えてくる。</h1><p class="muted">名前の入力・旗の読み取り・地図の位置は別々に記録。ヒントなしで別の3日にも正解し、3連続正解するとマスターです。</p><div class="fields card"><div><label for="masterScope">範囲</label><select id="masterScope">${scopeOptions()}</select></div><div><label for="masterRegion">地域</label><select id="masterRegion"><option>世界全体</option>${REGIONS.map(r=>`<option>${r}</option>`).join('')}</select></div><div><label for="masterFilter">状態</label><select id="masterFilter"><option value="all">すべて</option><option value="new">未挑戦</option><option value="review">復習したい</option><option value="master">マスターあり</option></select></div></div><div id="masterStats" class="section"></div><div class="list" id="masterList"></div>`;['masterScope','masterRegion','masterFilter'].forEach(id=>$('#'+id).onchange=renderMastery);renderMastery()}
function renderMastery(){const reg=$('#masterRegion').value,fil=$('#masterFilter').value,pool=data.filter(c=>inScope(c,$('#masterScope').value)&&(reg==='世界全体'||c.region===reg));let touched=0,mastered=0;const rows=pool.map(c=>{const rs=Object.keys(modeLabel).map(m=>record(c,m)),n=rs.reduce((a,r)=>a+r.right+r.wrong,0),chs=rs.flatMap(r=>Object.values(r.channels||{})),master=chs.some(r=>statusOf(r)==='マスター'),review=chs.some(r=>r.wrong&&!r.lastRight)||rs.some(r=>!r.channels&&r.wrong&&!r.lastRight);if(n)touched++;if(master)mastered++;return{c,n,master,review}}).filter(r=>fil==='all'||fil==='new'&&!r.n||fil==='review'&&r.review||fil==='master'&&r.master);$('#masterStats').innerHTML=`<div class="stats"><div class="card stat"><strong>${pool.length}</strong><span>この範囲の項目</span></div><div class="card stat"><strong>${touched}</strong><span>学習した項目</span></div><div class="card stat"><strong>${mastered}</strong><span>マスターした分野がある項目</span></div></div>`;$('#masterList').innerHTML=rows.map(({c,n,master,review})=>`<button class="countryRow" onclick="country('${c.id}')"><img class="miniFlag" src="${flagPath(c.id)}" alt=""><span>${esc(c.name)}<small>${master?'マスターあり':review?'復習したい':n?'練習中':'未挑戦'} · ${n}回学習</small></span></button>`).join('')||'<p>この条件の項目はありません。</p>'}
const flagGroups=[
{ids:['ID','MC','PL'],name:'赤と白の旗',text:'インドネシアとモナコは上が赤、下が白。ポーランドは上が白、下が赤です。インドネシアとモナコは図案だけでは区別しにくいため、地図の位置も一緒に覚えよう。'},
{ids:['RO','TD'],name:'青・黄・赤の縦じま',text:'ルーマニアとチャドは、とても似た3色の旗です。青の色合いに違いがありますが、画面によっても見え方が変わります。ヨーロッパとアフリカ、位置と組み合わせて覚えよう。'},
{ids:['IE','CI'],name:'緑とオレンジの順番',text:'アイルランドは旗ざお側から緑・白・オレンジ。コートジボワールはオレンジ・白・緑です。'},
{ids:['NL','LU'],name:'赤・白・青の横じま',text:'オランダは濃い青、ルクセンブルクは明るい青です。どちらもヨーロッパにあります。'},
{ids:['AU','NZ'],name:'南半球の星',text:'オーストラリアには白い星、ニュージーランドには白い縁の赤い星があります。'},
{ids:['NO','IS','DK','SE','FI'],name:'北ヨーロッパの十字',text:'十字の形は似ています。地の色と十字の色を組にして見よう。ノルウェーは赤地、アイスランドは青地です。'},
{ids:['SI','SK','RS','RU'],name:'3色と紋章',text:'スロベニア・スロバキア・セルビアは紋章が目印。ロシアの旗には紋章がありません。色の並びにも注目しよう。'},
{ids:['QA','BH'],name:'ぎざぎざの境目',text:'カタールはえんじ色と白、バーレーンは赤と白。境目のぎざぎざの数も異なります。'}];
function comparisonFor(c){return flagGroups.find(g=>g.ids.includes(c.id))}
function compareFlags(id){const g=id?comparisonFor(data.find(c=>c.id===id)||{}):null;if(g){showModal(`<span class="eyebrow">LOOK CLOSELY</span><h2>${g.name}</h2><div class="compareGrid">${g.ids.map(id=>{let c=data.find(c=>c.id===id);return`<div class="compareItem">${flag(c)}<b>${c.name}</b><p class="note">${c.region}</p></div>`}).join('')}</div><p>${g.text}</p><p class="note">旗自体の縦横比を保って共通の枠に収めています。インドネシアは縦:横=2:3、モナコは4:5です。採用する旗の種類は各国の図鑑で確認できます。</p><button class="primary" onclick="document.querySelector('#modal').close();practiceGroup('${g.ids[0]}')">この組み合わせを練習</button>`)}else{showModal(`<span class="eyebrow">FLAG LAB</span><h2>似ている旗を比べよう</h2><p>色の順番、星、紋章。違いを見つけてから練習しよう。</p><div class="list">${flagGroups.map(g=>`<button onclick="compareFlags('${g.ids[0]}')"><b>${g.name}</b><div class="row section">${g.ids.map(id=>`<img class="miniFlag" src="${flagPath(id)}" alt="">`).join('')}</div></button>`).join('')}</div>`)}}
function practiceGroup(id){const g=comparisonFor(data.find(c=>c.id===id));start({mode:'flag',region:'世界全体',level:'all',scope:'basic',input:'choice',count:g.ids.length,practice:'practice',ids:g.ids,review:false})}
function answerChoices(c,cfg){const available=data.filter(x=>x.id!==c.id&&inScope(x,cfg.scope||'basic'));const group=comparisonFor(c),near=shuffle(available.filter(x=>group?.ids.includes(x.id))),other=shuffle(available.filter(x=>!group?.ids.includes(x.id)));return shuffle([c,...near.concat(other).slice(0,3)])}
let inkModelPromise=null,inkEpoch=0;
function loadInkModel(){if(!inkModelPromise)inkModelPromise=fetch('assets/handwriting.json').then(r=>{if(!r.ok)throw Error('model');return r.json()}).catch(e=>{inkModelPromise=null;throw e});return inkModelPromise}
function mountHandwriting(){const epoch=++inkEpoch,s=session;$('#inkArea').innerHTML=`<p class="note">1文字ずつ書いて、候補を選びます。かな・カタカナと漢字（ベータ）に対応。英字は対象外です。</p><label for="inkScript">認識する文字</label><select id="inkScript"><option value="kana">かな・カタカナ</option><option value="kanji">漢字（ベータ）</option></select><p class="note"></p><svg id="inkPad" class="inkPad" viewBox="0 0 320 260" aria-label="1文字を書く手書き入力欄"><path class="inkGuide" d="M160 8V252M8 130H312"/><g id="inkLines"></g><text id="inkPlaceholder" x="160" y="140" text-anchor="middle">ここに1文字</text></svg><div class="row"><button id="inkUndo" type="button">1画戻す</button><button id="inkClear" type="button">書き直す</button><button id="inkRecognize" type="button" disabled>候補を出す</button></div><p id="inkStatus" class="note" aria-live="polite">認識データを読み込み中…</p><div id="inkCandidates" class="inkCandidates" aria-label="認識候補"></div><label for="inkText">組み立てた答え（修正できます）</label><input id="inkText" autocomplete="off" spellcheck="false" placeholder="候補を選ぶと、ここに入ります"><div class="row section"><button id="inkDelete" type="button">1文字消す</button><button id="inkSubmit" class="primary" type="button">この答えで回答</button><button id="inkKeyboard" type="button">キーボードへ切り替え</button></div><p class="note">端末内で認識するベータ機能です。標準の書き順・画数で大きく書いてください。認識候補を確認し、違う文字は修正してから回答できます。</p>`;let strokes=[],active=null,model=null,kanjiReady=false,recognizing=false;const pad=$('#inkPad'),lines=$('#inkLines'),alive=()=>epoch===inkEpoch&&session===s&&!s.done&&$('#inkPad')===pad;
 function redraw(){lines.innerHTML=[...strokes,...(active?[active.points]:[])].map(st=>`<path d="${st.map((p,i)=>(i?'L':'M')+p.map(n=>n.toFixed(1)).join(',')).join('')}"/>`).join('');$('#inkPlaceholder').style.display=strokes.length||active?'none':'';$('#inkRecognize').disabled=recognizing||($('#inkScript').value==='kanji'?!kanjiReady:!model)||!strokes.length||!!active;$('#inkUndo').disabled=!strokes.length;$('#inkClear').disabled=!strokes.length&&!active}
 function reset(){strokes=[];active=null;$('#inkCandidates').innerHTML='';redraw()}
 const point=e=>{const r=pad.getBoundingClientRect();return[(e.clientX-r.left)*320/r.width,(e.clientY-r.top)*260/r.height]};
 pad.onpointerdown=e=>{if(!alive()||active||e.button>0)return;e.preventDefault();active={id:e.pointerId,points:[point(e)]};pad.setPointerCapture(e.pointerId);$('#inkCandidates').innerHTML='';renderActive()};
 function renderActive(){redraw()}
 pad.onpointermove=e=>{if(!active||e.pointerId!==active.id)return;e.preventDefault();const p=point(e),last=active.points.at(-1);if(Math.hypot(p[0]-last[0],p[1]-last[1])>1.5){active.points.push(p);renderActive()}};
 pad.onpointerup=e=>{if(!active||e.pointerId!==active.id)return;active.points.push(point(e));strokes.push(active.points);active=null;redraw();$('#inkStatus').textContent=strokes.length+'画です。「候補を出す」を押してください。'};
 pad.onpointercancel=e=>{if(active?.id===e.pointerId){active=null;redraw()}};
 $('#inkUndo').onclick=()=>{strokes.pop();$('#inkCandidates').innerHTML='';redraw()};$('#inkClear').onclick=reset;
 $('#inkRecognize').onclick=async()=>{if(!alive()||recognizing||!strokes.length)return;const mode=$('#inkScript').value;if(mode==='kana'&&!model||mode==='kanji'&&!kanjiReady)return;const movement=strokes.reduce((sum,st)=>sum+st.slice(1).reduce((a,p,i)=>a+Math.hypot(p[0]-st[i][0],p[1]-st[i][1]),0),0);if(movement<8){$('#inkStatus').textContent='もう少し大きく書いてください。';return}recognizing=true;redraw();$('#inkStatus').textContent='候補を調べています…';try{const candidates=mode==='kanji'?[...new Set((await KanjiEngine.recognize(strokes)).trim().split(/\s+/).filter(Boolean))].map(char=>({char})):InkRecognizer.recognize(strokes,model.characters,12);if(!alive()||$('#inkScript').value!==mode)return;$('#inkCandidates').innerHTML=candidates.map(c=>`<button type="button" data-ink-char="${esc(c.char)}">${esc(c.char)}</button>`).join('');$('#inkStatus').textContent=candidates.length?'候補から1文字選んでください。違う文字は答え欄でも修正できます。':'候補がありません。書き直すか、答え欄に入力してください。';$('#inkCandidates').onclick=e=>{const b=e.target.closest('[data-ink-char]');if(!b||!alive())return;$('#inkText').value+=b.dataset.inkChar;reset();$('#inkStatus').textContent='次の文字を書くか、この答えで回答してください。'}}catch(err){if(alive()){$('#inkStatus').textContent=/[ぁ-んァ-ン一-龯]/.test(err.message)?err.message:'認識できませんでした。書き直すか、キーボードで修正してください。';$('#inkRetry').hidden=false;kanjiReady=false}}finally{recognizing=false;if(alive())redraw()}};
 $('#inkDelete').onclick=()=>{$('#inkText').value=Array.from($('#inkText').value).slice(0,-1).join('')};$('#inkSubmit').onclick=()=>submitAnswer();$('#inkKeyboard').onclick=()=>{if(!alive())return;const text=$('#inkText').value;const usedHints=s.hint;s.cfg.input='text';s.inputChanged=true;if(s.mixed){s.queue[s.i].task.input='text';s.inputChanged=true}question();s.hint=usedHints;$('#answer').value=text;renderHintHistory()};
 const retry=document.createElement('button');retry.id='inkRetry';retry.type='button';retry.textContent='認識データを再読み込み';retry.hidden=true;$('#inkStatus').after(retry);
 async function prepareInk(){const mode=$('#inkScript').value;$('#inkRetry').hidden=true;$('#inkStatus').textContent=mode==='kanji'?'漢字認識データ（約6.7MB）を読み込み中…':'かな認識データを読み込み中…';try{if(mode==='kanji'){if(!window.KanjiEngine)throw Error('漢字認識を読み込めませんでした。ページを再読み込みしてください。');const info=await KanjiEngine.load();kanjiReady=true;if(!alive()||$('#inkScript').value!==mode)return;$('#inkStatus').textContent=`${info.characters}字の漢字認識を準備しました。1文字ずつ、画を分けて書いてください。`;}else{const m=await loadInkModel();if(!m.characters||!window.InkRecognizer)throw Error('かな認識データを読み込めませんでした。');model=m;if(!alive()||$('#inkScript').value!==mode)return;$('#inkStatus').textContent='かな入力を準備しました。1文字ずつ書いてください。';}redraw()}catch(err){if(alive()){$('#inkStatus').textContent=err.message||'認識データを読み込めませんでした。再試行できます。';$('#inkRetry').hidden=false;redraw()}}}
 $('#inkScript').onchange=()=>{recognizing=false;$('#inkCandidates').innerHTML='';prepareInk();redraw()};retry.onclick=prepareInk;prepareInk();redraw();
}

const terrainCategories={mountain:'山',range:'山脈',river:'川',lake:'湖',island:'島',archipelago:'諸島',peninsula:'半島'};
const terrainModes={terrainName:'地図から名前',terrainLocation:'名前から位置'};
const terrainById=id=>terrain.find(q=>q.id===id);
function terrainSetup(review=false){view='terrainSetup';const prev=session?.cfg.content==='terrain'?session.cfg:null;app.innerHTML=`<div class="setup"><button class="back" onclick="home()">← ホーム</button><span class="eyebrow">WORLD LANDSCAPES · ${review?'REVIEW':'EXPLORE'}</span><h1>${review?'地形の苦手を、得意に。':'世界の自然を、たどろう。'}</h1><form class="card" id="terrainSetup"><div class="fields"><div><label for="terrainCategory">カテゴリー</label><select id="terrainCategory"><option value="all">すべての地形（${terrain.length}）</option>${Object.entries(terrainCategories).map(([k,v])=>`<option value="${k}">${v}（${terrain.filter(q=>q.category===k).length}）</option>`).join('')}</select></div><div><label for="terrainRegion">地域</label><select id="terrainRegion"><option>世界全体</option>${REGIONS.map(r=>`<option>${r}</option>`).join('')}</select></div><div><label for="terrainMode">学び方</label><select id="terrainMode"><option value="terrainName">地図から名前を答える</option><option value="terrainLocation">名前から位置を選ぶ</option></select></div><div><label for="terrainInput">名前の回答方法</label><select id="terrainInput"><option value="text">キーボード入力</option><option value="choice">4択</option><option value="ink">手書き・かな（ベータ）</option></select></div><div><label for="terrainLevel">難易度</label><select id="terrainLevel"><option value="all">基本・全収録対象</option><option value="intro">入門・各カテゴリーの代表例</option></select></div><div><label for="terrainCount">問題数</label><select id="terrainCount"><option>10</option><option>5</option><option>20</option><option>30</option></select></div><div><label for="terrainPractice">プレイ形式</label><select id="terrainPractice"><option value="practice">練習・ヒントあり</option><option value="test">テスト・ヒントなし</option></select></div></div><p class="note">山は地点、川は流路、湖は水域、山脈・島・諸島・半島は学習用の範囲で示します。問題数は選んだ範囲の項目数までです。</p><button class="primary" type="submit">${review?'復習':'地形の学習'}をはじめる →</button><p id="setupMsg" aria-live="polite"></p></form><div class="row section"><button onclick="terrainAtlas()">地形図鑑</button><button onclick="terrainSources()">出典と地図の精度</button></div></div>`;
const keys={terrainCategory:'category',terrainRegion:'region',terrainMode:'mode',terrainInput:'input',terrainLevel:'level',terrainCount:'count',terrainPractice:'practice'};if(prev)for(const[id,k]of Object.entries(keys))if(prev[k]!==undefined&&[...$('#'+id).options].some(o=>o.value===String(prev[k])))$('#'+id).value=String(prev[k]);$('#terrainMode').onchange=()=>{$('#terrainInput').disabled=$('#terrainMode').value==='terrainLocation'};$('#terrainMode').onchange();$('#terrainSetup').onsubmit=e=>{e.preventDefault();const cfg={content:'terrain',scope:'all',review};for(const[id,k]of Object.entries(keys))cfg[k]=$('#'+id).value;cfg.count=+cfg.count;terrainStart(cfg)}}
function terrainStart(cfg){cfg={content:'terrain',scope:'all',category:'all',region:'世界全体',mode:'terrainName',input:'text',level:'all',count:10,practice:'practice',review:false,...cfg};cfg.count=Math.max(1,Math.min(terrain.length,Math.floor(+cfg.count)||10));let pool=terrain.filter(q=>(cfg.category==='all'||cfg.category===q.category)&&(cfg.region==='世界全体'||q.regions.includes(cfg.region))&&(cfg.level==='all'||q.level==='intro')&&(!cfg.ids||cfg.ids.includes(q.id)));if(cfg.review)pool=pool.filter(q=>{const r=channelRecord(q,cfg.mode,cfg.input);return r.wrong&&(!r.lastRight||Date.now()-r.last>7*86400000)});if(!pool.length){if($('#setupMsg'))$('#setupMsg').textContent=cfg.review?'この条件の復習問題はありません。カテゴリー・地域・回答方法を変えてみましょう。':'この条件の問題はありません。条件を変えてみましょう。';return false}pool=shuffle(pool);if(cfg.review)pool.sort((a,b)=>channelRecord(a,cfg.mode,cfg.input).last-channelRecord(b,cfg.mode,cfg.input).last);session={cfg,queue:pool.slice(0,cfg.count),i:0,results:[],began:Date.now(),selected:null,done:false,hint:0};question();return true}
function relatedNames(q){return q.countries.map(id=>data.find(c=>c.id===id)?.name||id).join('・')}
function terrainChoices(q){return shuffle([q,...shuffle(terrain.filter(x=>x.category===q.category&&x.id!==q.id)).slice(0,3)])}
let terrainMapAPI=null;
function terrainQuestion(){view='game';const s=session,q=s.queue[s.i],loc=s.cfg.mode==='terrainLocation';s.done=false;s.selected=null;s.hint=0;s.options=terrainChoices(q);app.innerHTML=`<button class="back" onclick="leave()">← 学習を終了</button><div class="row between"><span class="eyebrow">${terrainCategoryLabel(q.category)} · ${terrainModes[s.cfg.mode]} · ${s.cfg.practice==='test'?'テスト':'練習'}</span><b>${s.i+1} / ${s.queue.length} 問</b></div><div class="progress"><i style="width:${s.i/s.queue.length*100}%"></i></div><div class="gameLayout"><div><div id="terrainMap"></div><p class="note">${esc(q.accuracy)}</p></div><section class="card answerPanel"><h2>${loc?nameMarkup(q)+'は、どこ？':`示されている${terrainCategoryLabel(q.category)}の名前は？`}</h2><div id="answerArea">${loc?'<p class="muted">地図のA〜Dの形を選び、回答を確定しよう。線や範囲をタップして選べます。</p><div id="locationChoices" class="choices"></div><p id="selection" aria-live="polite">まだ選ばれていません</p><button id="submitLocation" disabled class="primary" onclick="submitAnswer()">回答する</button>':s.cfg.input==='ink'?'<div id="inkArea"></div>':s.cfg.input==='choice'?'<div class="choices" id="choices"></div>':'<form id="answerForm"><label for="answer">地形の名前</label><input id="answer" autocomplete="off" spellcheck="false" placeholder="漢字・かな・登録済みの英語名"><p class="note">例：ふじさん、アンデス山脈。読み方でも答えられます。</p><button class="primary" type="submit">回答する</button></form>'}<div class="row section">${s.cfg.practice==='practice'?'<button onclick="hint()">ヒント</button>':''}<button onclick="submitAnswer(true)">わからない</button></div><p id="hint" class="note" aria-live="polite"></p></div><div id="feedback" aria-live="polite"></div></section></div>`;
terrainMapAPI=mountTerrainMap($('#terrainMap'),loc?s.options:[q],{labels:loc,onSelect:loc?terrainSelect:null});if(!loc)terrainMapAPI.focus(q);
if(loc){$('#locationChoices').innerHTML=s.options.map((x,i)=>`<button data-location="${x.id}" aria-label="候補${'ABCD'[i]}を選ぶ">候補 ${'ABCD'[i]}</button>`).join('');$('#locationChoices').onclick=e=>{const b=e.target.closest('[data-location]');if(b)terrainSelect(b.dataset.location)}}else if(s.cfg.input==='ink')mountHandwriting();else if(s.cfg.input==='choice'){$('#choices').innerHTML=s.options.map(x=>`<button data-answer="${x.id}">${esc(x.name)}</button>`).join('');$('#choices').onclick=e=>{const b=e.target.closest('[data-answer]');if(b)submitAnswer(false,b.dataset.answer)}}else{$('#answerForm').onsubmit=e=>{e.preventDefault();submitAnswer()};$('#answer').onkeydown=e=>{if(e.key==='Enter'&&(e.isComposing||e.keyCode===229)){e.preventDefault();e.stopPropagation()}}}}
function terrainSelect(id){const s=session;if(s?.done||!s?.options.some(q=>q.id===id))return;s.selected=id;terrainMapAPI.select(id);$('#selection').textContent=`候補 ${'ABCD'[s.options.findIndex(q=>q.id===id)]} を選択しました`;$('#submitLocation').disabled=false;document.querySelectorAll('[data-location]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.location===id)))}
function terrainHint(){const s=session,q=s.queue[s.i];s.hint++;$('#hint').textContent=s.hint===1?`地域：${q.regions.join('・')}`:s.hint===2?`主な関係国・地域：${relatedNames(q)}`:`名前の最初：${q.reading.slice(0,1)}`;if(s.cfg.mode==='terrainLocation'&&s.hint>=2)terrainMapAPI.focus(q)}
function terrainAnswer(skip=false,choice=null){const s=session;if(!s||s.done)return;const q=s.queue[s.i],m=s.cfg.mode,loc=m==='terrainLocation',a=skip?'':loc?s.selected:choice||$('#inkText')?.value||$('#answer')?.value||'';if(!skip&&!String(a||'').trim())return;const ok=!skip&&(loc||choice?a===q.id:accepted(q,a));s.done=true;const r=record(q,m),today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Tokyo'});r[ok?'right':'wrong']++;r.last=Date.now();r.lastRight=ok;r.streak=ok&&!s.hint?r.streak+1:0;if(ok&&!s.hint&&!r.dates.includes(today))r.dates.push(today);r.hinted=(r.hinted||0)+(s.hint?1:0);updateChannel(r,s.cfg,m,ok,s.hint,today);db.records[q.id+':'+m]=r;s.results.push({id:q.id,ok,hint:s.hint,answer:a,input:channelKey(m,s.cfg.input),mode:m,content:s.cfg.content||'country'});save();$('#answerArea').hidden=true;$('#feedback').innerHTML=`<div class="${ok?'good':'bad'}"><b>${ok?'正解！':'ここで覚えよう'}</b><h2>${nameMarkup(q)}</h2><p>${esc(q.description)}</p><p class="note">主な関係国・地域：${esc(relatedNames(q))}<br>複数国の地形は国境で区切らずに表示しています。</p><button class="primary" onclick="next()">${s.i+1===s.queue.length?'結果を見る':'次の問題へ'} →</button><button onclick="terrainDetail('${q.id}')">図鑑で詳しく</button></div>`;terrainMapAPI.reveal(q.id,s.selected);}
function terrainResult(){view='result';const s=session,n=s.results.length,right=s.results.filter(r=>r.ok).length;db.history.unshift({at:Date.now(),content:'terrain',mode:s.cfg.mode,region:s.cfg.region,input:new Set(s.results.map(r=>r.input)).size>1?'mixed':s.cfg.input,scope:'all',practice:s.cfg.practice,right,n,category:s.cfg.category});db.history=db.history.slice(0,100);save();app.innerHTML=`<div class="setup"><span class="eyebrow">WORLD LANDSCAPES · COMPLETE</span><h1>自然の形が、見えてきた。</h1><section class="card"><div class="resultScore">${right}<span style="font-size:24px"> / ${n}</span></div><p>山の位置、川の流れ、島のまとまり。図鑑でも確かめよう。</p><div class="row"><button class="primary" onclick="terrainSetup(true)">地形を復習</button><button onclick="terrainSetup()">もう一度挑戦</button><button onclick="terrainAtlas()">地形図鑑</button><button onclick="home()">ホーム</button><button onclick="showResultCard()">結果画像をつくる</button></div></section><div class="list section">${s.results.map(r=>{const q=terrainById(r.id);return`<button class="countryRow" onclick="terrainDetail('${q.id}')"><span class="terrainIcon">${terrainSymbol(q.category)}</span><span>${r.ok?'○':'×'} ${esc(q.name)}<small>${terrainCategoryLabel(q.category)} · ${r.hint?'ヒントあり':'ヒントなし'}</small></span></button>`}).join('')}</div></div>`}
function terrainSymbol(cat){const basic={mountain:'▲',range:'⋀⋀',river:'〜',lake:'◒',island:'◈',archipelago:'∴',peninsula:'⊃'};if(Object.hasOwn(basic,cat))return basic[cat];const paths={sea:'M3 9Q6 5 9 9T15 9T21 9M3 14Q6 10 9 14T15 14T21 14M3 19Q6 15 9 19T15 19T21 19',bay:'M20 3H12Q3 3 3 12T12 21H20M11 9Q13 7 15 9T20 9M11 15Q13 13 15 15T20 15',strait:'M3 3Q12 7 7 12Q12 17 3 21M21 3Q12 7 17 12Q12 17 21 21M9 12H15M13 10L15 12L13 14',desert:'M2 19Q8 8 14 19M9 19Q15 11 22 19M16 5H19M17.5 3.5V6.5',plain:'M2 15H22M3 19H21M6 15V10M4 11L6 9L8 11M17 15V10M15 11L17 9L19 11',plateau:'M2 20L7 7H17L22 20M7 7H17M3 20H21'};return Object.hasOwn(paths,cat)?`<svg class="terrainGlyph" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="${paths[cat]}"/></svg>`:'◇'}
function terrainCategoryLabel(cat){return Object.hasOwn(terrainCategories,cat)?terrainCategories[cat]:'その他の地形'}
function terrainAtlas(){view='terrainAtlas';app.innerHTML=`<button class="back" onclick="home()">← ホーム</button><span class="eyebrow">NATURE ATLAS</span><h1>地形を知る、世界を知る。</h1><p class="muted">名前・読み・関係国で探せます。項目を選ぶと形と学習記録を確認できます。</p><div class="fields card"><div><label for="terrainSearch">検索</label><input id="terrainSearch" placeholder="ナイル / ないる / エジプト"></div><div><label for="atlasCategory">カテゴリー</label><select id="atlasCategory"><option value="all">すべて</option>${Object.entries(terrainCategories).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div><label for="atlasTerrainRegion">地域</label><select id="atlasTerrainRegion"><option>世界全体</option>${REGIONS.map(r=>`<option>${r}</option>`).join('')}</select></div><div><label for="terrainState">学習状態</label><select id="terrainState"><option value="all">すべて</option><option value="new">未挑戦</option><option value="review">復習したい</option><option value="master">マスターあり</option></select></div></div><div id="terrainStats" class="section"></div><div id="terrainList" class="list section"></div>`;['terrainSearch','atlasCategory','atlasTerrainRegion','terrainState'].forEach(id=>$('#'+id).oninput=renderTerrainAtlas);renderTerrainAtlas()}
function renderTerrainAtlas(){const search=norm($('#terrainSearch').value),cat=$('#atlasCategory').value,reg=$('#atlasTerrainRegion').value,state=$('#terrainState').value;let base=terrain.filter(q=>(cat==='all'||q.category===cat)&&(reg==='世界全体'||q.regions.includes(reg))&&[...q.aliases,relatedNames(q)].some(n=>norm(n).includes(search)));const rows=base.map(q=>{const rs=Object.keys(terrainModes).map(m=>record(q,m)),n=rs.reduce((a,r)=>a+r.right+r.wrong,0),chs=rs.flatMap(r=>Object.values(r.channels||{}));return{q,n,master:chs.some(r=>statusOf(r)==='マスター'),review:chs.some(r=>r.wrong&&!r.lastRight)}});$('#terrainStats').innerHTML=`<div class="stats"><div class="card stat"><strong>${base.length}</strong><span>この条件の地形</span></div><div class="card stat"><strong>${rows.filter(r=>r.n).length}</strong><span>学習済み</span></div><div class="card stat"><strong>${rows.filter(r=>r.master).length}</strong><span>マスターあり</span></div></div>`;$('#terrainList').innerHTML=rows.filter(r=>state==='all'||state==='new'&&!r.n||state==='review'&&r.review||state==='master'&&r.master).map(({q,n,review,master})=>`<button class="countryRow" onclick="terrainDetail('${q.id}')"><span class="terrainIcon">${terrainSymbol(q.category)}</span><span>${esc(q.name)}<small>${terrainCategoryLabel(q.category)} · ${q.regions.join('・')}</small><small>${master?'マスターあり':review?'復習したい':n?'練習中':'未挑戦'} · ${n}回学習</small></span></button>`).join('')||'<p>この条件の地形はありません。</p>'}
function terrainDetail(id){const q=terrainById(id);if(!q)return;showModal(`<span class="eyebrow">NATURE ATLAS · ${terrainCategoryLabel(q.category)}</span><h2>${nameMarkup(q)}</h2><p>${esc(q.description)}</p><div id="terrainDetailMap"></div><p class="note">表示：${esc(q.accuracy)}<br>主な関係国・地域（全域の一覧ではありません）：${esc(relatedNames(q))}</p><div class="skillGrid">${Object.entries(terrainModes).map(([m,label])=>{const r=record(q,m);return`<div class="skill"><b>${label}</b><p>${r.right}正解 / ${r.wrong}不正解</p>${skillDetails(r,m)}</div>`}).join('')}</div><div class="row section"><button class="primary" onclick="document.querySelector('#modal').close();terrainStart({ids:['${q.id}'],count:1})">名前を練習</button><button onclick="document.querySelector('#modal').close();terrainStart({ids:['${q.id}'],mode:'terrainLocation',count:1})">位置を練習</button></div><details><summary>出典・精度</summary><p class="note">${q.sources.map(x=>`<a href="${x.url}" target="_blank" rel="noopener">${esc(x.title)}</a>`).join('<br>')}<br>${q.sourceLayer} / ${esc(q.sourceNames.join('・'))}<br>${q.license} · 確認日 ${q.checked}<br>学習用の簡略地図です。国境は領有権や地形の範囲を確定するものではありません。</p></details>`);mountTerrainMap($('#terrainDetailMap'),[q]).focus(q)}
function terrainSources(){showModal(`<h2>地形データと精度</h2><p>${terrain.length}項目を収録しています。世界の地形を網羅した一覧ではありません。</p><p><a href="https://www.naturalearthdata.com/downloads/10m-physical-vectors/" target="_blank" rel="noopener">Natural Earth 1:10m</a>：山頂の位置、山脈・島・諸島・半島の学習用範囲。<br><a href="https://www.naturalearthdata.com/downloads/50m-physical-vectors/" target="_blank" rel="noopener">Natural Earth 1:50m</a>：河川の主な流路、湖の水域。</p><p>パブリックドメインのデータを簡略化しています。山脈や半島などの境界は定義に幅があり、厳密な境界ではありません。諸島の表示には島々の間の海域を含む場合があります。</p><p>川は上流・河口の分流・支流をすべて示していません。湖内を結ぶ中心線が含まれる場合があります。イベリア半島はスペイン・ポルトガルの本土地図を結合して近似しています。</p><p>地図は正距円筒図法です。面積・形がゆがむため、画面上の大きさによる面積比較には使わないでください。個々の項目の図鑑で出典名・確認日・精度を確認できます。</p>`)}
function mountTerrainMap(host,items,opt={}){const NS='http://www.w3.org/2000/svg',make=(t,a)=>{const el=document.createElementNS(NS,t);for(const[k,v]of Object.entries(a))el.setAttribute(k,v);return el},pos=([x,y])=>[(x+180)*2,(85-y)*2];let visual=[],letters=[],vb=[0,0,720,340],selected=null,correct=null,wrong=null;
 function rescale(b){vb=b;const r=host.getBoundingClientRect(),scale=Math.max(b[2]/(r.width||800),b[3]/(r.height||470));for(const o of visual)if(o.marker)o.marker.setAttribute('transform',`translate(${o.x},${o.y}) scale(${scale*8})`);for(const l of letters){l.setAttribute('font-size',scale*16);l.setAttribute('stroke-width',scale*3);l.setAttribute('dx',scale*10);l.setAttribute('dy',-scale*8)}}
 const api=mountMap(host,{terrain:true,onFeatureSelect:opt.onSelect,onViewChange:rescale}),svg=host.querySelector('svg'),g=svg.querySelector('g'),layer=make('g',{'aria-label':'学習する地形'});g.append(layer);host.querySelector('.mapCaption').textContent='Natural Earth · 地形の範囲・流路は学習用の簡略表示';
 function line(coords,close=false){return coords.map((p,i)=>(i?'L':'M')+pos(p).map(x=>x.toFixed(3)).join(',')).join('')+(close?'Z':'')}
 function path(geom){const c=geom.coordinates;switch(geom.type){case'LineString':return line(c);case'MultiLineString':return c.map(x=>line(x)).join('');case'Polygon':return c.map(x=>line(x,true)).join('');case'MultiPolygon':return c.map(p=>p.map(x=>line(x,true)).join('')).join('');default:return''}}
 for(const[qIndex,q]of items.entries()){const group=make('g',{'data-feature-id':q.id}),[x,y]=pos([q.lng,q.lat]);layer.append(group);let marker=null,visible;
 if(q.geometry.type==='Point'){marker=make('g',{});group.append(marker);visible=make('path',{d:q.category==='heritage'?'M-0.9,-0.9H0.9V0.9H-0.9Z':'M0,-1.1L-1,0.9L1,0.9Z',style:'fill:#c77738;stroke:white;stroke-width:1.5;vector-effect:non-scaling-stroke;pointer-events:none'});marker.append(visible);marker.append(make('path',{d:'M0,-2L-2,2L2,2Z','data-terrain':q.id,style:'fill:transparent;stroke:transparent;pointer-events:all'}))}
 else{const d=path(q.geometry),isLine=q.geometry.type.includes('Line');visible=make('path',{d,'fill-rule':'evenodd',style:`fill:${isLine?'none':['lake','sea','bay','strait'].includes(q.category)?'#64a7c3':'#dba26e'};fill-opacity:.55;stroke:${isLine?'#246f9e':'#9d673b'};stroke-width:${isLine?3.5:2};vector-effect:non-scaling-stroke;pointer-events:none`});group.append(visible);group.append(make('path',{d,'data-terrain':q.id,'fill-rule':'evenodd',style:`fill:${isLine?'none':'transparent'};stroke:transparent;stroke-width:${isLine?20:12};vector-effect:non-scaling-stroke;pointer-events:${isLine?'stroke':'all'}`}))}
 visual.push({q,visible,marker,x,y});if(opt.labels){const label=make('text',{x,y,'data-terrain':q.id,style:'fill:#173e35;stroke:white;paint-order:stroke;font-weight:900;cursor:pointer'});label.textContent=q.mapLabel||'ABCD'[qIndex];group.append(label);letters.push(label)}}
 function paint(){for(const o of visual){const color=o.q.id===correct?'#197356':o.q.id===wrong?'#b45431':o.q.id===selected?'#285fbc':o.q.category==='river'?'#246f9e':'#a76b37';o.visible.style.stroke=color;if(!o.q.geometry.type.includes('Line'))o.visible.style.fill=o.q.id===correct?'#76b68c':o.q.id===selected?'#79a2d3':['lake','sea','bay','strait'].includes(o.q.category)?'#64a7c3':'#dba26e';o.visible.style.strokeWidth=o.q.id===selected||o.q.id===correct?'4':'2.5'}}
 rescale(vb);return{fit(bounds){api.fit(bounds)},focus(q){api.fit(q.bbox)},select(id){selected=id;paint()},reveal(id,guess){correct=id;wrong=guess&&guess!==id?guess:null;selected=null;paint();const shown=items.filter(q=>q.id===id||q.id===guess);api.fit([Math.min(...shown.map(q=>q.bbox[0])),Math.min(...shown.map(q=>q.bbox[1])),Math.max(...shown.map(q=>q.bbox[2])),Math.max(...shown.map(q=>q.bbox[3]))])},svg};}

const heritageKinds={cultural:'文化遺産',natural:'自然遺産',mixed:'複合遺産'};
const heritageModes={heritagePhoto:'写真から名前',heritageMap:'地図から名前',heritageLocation:'名前から位置',heritageCountry:'所在国を答える',heritageType:'遺産の種類'};
const heritageById=id=>heritage.find(q=>q.id===id);
function heritageCountryName(id){return id==='VA'?'聖座（バチカン）':data.find(c=>c.id===id)?.name||id}
function heritageCredits(q,full=false){if(!q.photo)return '<p class="note">写真は未収録。地図・説明で学べます。</p>';const p=q.photo;return `<p class="photoCredit">写真：${esc(p.author)} · ${!full&&/\/wiki\/File(?::|%3A)/i.test(p.licenseUrl)?esc(p.license):`<a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener">${esc(p.license)}</a>`}${full?`<br><a href="${esc(p.sourcePage)}" target="_blank" rel="noopener">${esc(p.fileTitle)}</a> · ${esc(p.changes)}`:''}</p>`}
function heritagePhoto(q,revealed=false){if(!q.photo)return `<div class="photoPlaceholder">世界遺産 · 地図で学ぶ</div>`;return `<figure class="heritagePhoto"><img src="${q.photo?.path||''}" alt="${revealed?esc(q.photoSubject):'出題する世界遺産の写真'}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><div class="photoError" hidden>写真を読み込めませんでした。<button onclick="retryHeritagePhoto(this)">再読み込み</button><p>解けない場合は終了して地図問題に切り替えられます。</p></div>${revealed?`<figcaption>${esc(q.photoSubject)}</figcaption>`:''}</figure>${heritageCredits(q,revealed)}`}
function heritageSetup(review=false){view='heritageSetup';const prev=session?.cfg.content==='heritage'?session.cfg:null;app.innerHTML=`<div class="setup"><button class="back" onclick="home()">← ホーム</button><span class="eyebrow">WORLD HERITAGE · ${review?'REVIEW':'DISCOVER'}</span><h1>${review?'世界遺産を、もう一度。':'写真の向こうに、世界の宝。'}</h1><form class="card" id="heritageSetup"><div class="fields"><div><label for="heritageMode">学び方</label><select id="heritageMode">${Object.entries(heritageModes).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div><label for="heritageInput">名前の回答方法</label><select id="heritageInput"><option value="text">キーボード入力</option><option value="choice">4択</option><option value="ink">手書き・かな（ベータ）</option></select></div><div><label for="heritageKind">種類</label><select id="heritageKind"><option value="all">すべて</option>${Object.entries(heritageKinds).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div><label for="heritageRegion">地域</label><select id="heritageRegion"><option>世界全体</option>${REGIONS.map(r=>`<option>${r}</option>`).join('')}</select></div><div><label for="heritageCount">問題数</label><select id="heritageCount"><option>10</option><option>5</option><option>20</option></select></div><div><label for="heritagePractice">プレイ形式</label><select id="heritagePractice"><option value="practice">練習・ヒントあり</option><option value="test">テスト・ヒントなし</option></select></div></div><p class="note">${heritage.length}件の代表例を収録。すべての世界遺産を網羅したものではありません。写真問題では、出題文で示す構成資産の名前も受け付けます。地図問題では登録名・登録済みの略称で答えてください。</p><button class="primary" type="submit">${review?'復習':'世界遺産の学習'}をはじめる →</button><p id="setupMsg" aria-live="polite"></p></form><div class="row section"><button onclick="heritageAtlas()">世界遺産図鑑</button><button onclick="heritageSources()">情報・写真の出典</button></div></div>`;const keys={heritageMode:'mode',heritageInput:'input',heritageKind:'kind',heritageRegion:'region',heritageCount:'count',heritagePractice:'practice'};if(prev)for(const[id,k]of Object.entries(keys))if([...$('#'+id).options].some(o=>o.value===String(prev[k])))$('#'+id).value=String(prev[k]);$('#heritageMode').onchange=()=>{$('#heritageInput').disabled=!['heritagePhoto','heritageMap'].includes($('#heritageMode').value)};$('#heritageMode').onchange();$('#heritageSetup').onsubmit=e=>{e.preventDefault();const cfg={review};for(const[id,k]of Object.entries(keys))cfg[k]=$('#'+id).value;heritageStart(cfg)}}
function heritageStart(cfg={}){cfg={content:'heritage',scope:'all',mode:'heritagePhoto',input:'text',kind:'all',region:'世界全体',count:10,practice:'practice',review:false,...cfg};if(['heritageCountry','heritageType'].includes(cfg.mode))cfg.input='choice';cfg.count=Math.max(1,Math.min(heritage.length,Math.floor(+cfg.count)||10));let pool=heritage.filter(q=>(cfg.kind==='all'||cfg.kind===q.kind)&&(cfg.region==='世界全体'||q.regions.includes(cfg.region))&&(!cfg.ids||cfg.ids.includes(q.id)));if(cfg.review)pool=pool.filter(q=>{const r=channelRecord(q,cfg.mode,cfg.input);return r.wrong&&(!r.lastRight||Date.now()-r.last>7*86400000)});if(!pool.length){if($('#setupMsg'))$('#setupMsg').textContent='この条件の問題はありません。学び方・地域・種類・回答方法を変えてみましょう。';return false}pool=shuffle(pool);if(cfg.review)pool.sort((a,b)=>channelRecord(a,cfg.mode,cfg.input).last-channelRecord(b,cfg.mode,cfg.input).last);session={cfg,queue:pool.slice(0,cfg.count),i:0,results:[],began:Date.now(),done:false,hint:0};question();return true}
function heritageOptions(q){return shuffle([q,...shuffle(heritage.filter(x=>x.id!==q.id)).slice(0,3)])}
function mountHeritageMap(host,items,opt={}){const points=items.flatMap((q,i)=>q.positions.map(p=>({...q,category:'heritage',lat:p.lat,lng:p.lng,geometry:{type:'Point',coordinates:[p.lng,p.lat]},mapLabel:'ABCD'[i]})));const api=mountTerrainMap(host,points,opt);host.querySelector('.mapCaption').textContent='UNESCO掲載地点 · 四角は位置の目安／登録範囲の境界ではありません';return api}
let heritageMapAPI=null;
function heritageQuestion(){view='game';const s=session,q=s.queue[s.i],m=s.cfg.mode,photo=m==='heritagePhoto',loc=m==='heritageLocation',country=m==='heritageCountry',type=m==='heritageType';s.done=false;s.selected=null;s.hint=0;s.countrySelection=new Set();s.options=heritageOptions(q);const prompt=photo?(q.photoHint?'この写真が撮影された世界遺産の名前は？':q.photoAnswers.length?'写真に写る代表的な構成資産の名前、または世界遺産の登録名は？':'この写真の世界遺産の名前は？'):loc?nameMarkup(q)+'は、どこ？':country?nameMarkup(q)+'の所在国をすべて選ぼう':type?nameMarkup(q)+'は、どの種類？':'地図に示した世界遺産の名前は？';app.innerHTML=`<button class="back" onclick="leave()">← 学習を終了</button><div class="row between"><span class="eyebrow">WORLD HERITAGE · ${heritageModes[m]} · ${s.cfg.practice==='test'?'テスト':'練習'}</span><b>${s.i+1} / ${s.queue.length} 問</b></div><div class="progress"><i style="width:${s.i/s.queue.length*100}%"></i></div><div class="gameLayout"><div id="heritageVisual">${photo?heritagePhoto(q):loc||m==='heritageMap'?'<div id="heritageMap"></div>':heritagePhoto(q)}</div><section class="card answerPanel"><h2>${prompt}</h2>${photo&&q.photoHint?`<p class="notice">${esc(q.photoHint)}</p>`:''}${photo&&q.unescoId==='1314'?'<p class="notice">北海沿岸の干潟。複数国にまたがる自然遺産です。</p>':''}${photo&&q.unescoId==='156'?'<p class="notice">タンザニアの草原が広がる国立公園です。</p>':''}${photo&&q.unescoId==='303'?'<p class="notice">アルゼンチン側の国立公園を出題しています。</p>':''}<div id="answerArea">${loc?'<p class="note">同じ文字の四角は、一つの遺産に属する複数地点です。</p><div id="heritageLocations" class="choices"></div><p id="selection" aria-live="polite">まだ選ばれていません</p><button id="submitLocation" class="primary" disabled onclick="submitAnswer()">回答する</button>':country?'<p class="note">複数選択できます。UNESCOの登録上の所在国をすべて選んでから確定してください。</p><div id="heritageCountries" class="choices"></div><button class="primary" onclick="submitAnswer()">回答する</button>':type?'<div id="heritageTypes" class="choices"></div>':s.cfg.input==='ink'?'<div id="inkArea"></div>':s.cfg.input==='choice'?'<div class="choices" id="choices"></div>':'<form id="answerForm"><label for="answer">名前</label><input id="answer" autocomplete="off" spellcheck="false" placeholder="登録名・略称・読み方"><button class="primary section" type="submit">回答する</button></form>'}<div class="row section">${s.cfg.practice==='practice'?'<button onclick="hint()">ヒント</button>':''}<button onclick="submitAnswer(true)">わからない</button></div><p id="hint" class="note" aria-live="polite"></p></div><div id="feedback" aria-live="polite"></div></section></div>`;
if(loc||m==='heritageMap'){heritageMapAPI=mountHeritageMap($('#heritageMap'),loc?s.options:[q],{labels:loc,onSelect:loc?heritageSelect:null});if(!loc)heritageMapAPI.focus(q)}
if(loc){$('#heritageLocations').innerHTML=s.options.map((x,i)=>`<button data-heritage-location="${x.id}">候補 ${'ABCD'[i]}</button>`).join('');$('#heritageLocations').onclick=e=>{const b=e.target.closest('[data-heritage-location]');if(b)heritageSelect(b.dataset.heritageLocation)}}
else if(country){const ids=shuffle([...q.countries,...shuffle(data.filter(c=>c.scope==='un'&&!q.countries.includes(c.id))).slice(0,Math.max(3,6-q.countries.length)).map(c=>c.id)]);$('#heritageCountries').innerHTML=ids.map(id=>`<button data-country="${id}" aria-pressed="false">${esc(heritageCountryName(id))}</button>`).join('');$('#heritageCountries').onclick=e=>{const b=e.target.closest('[data-country]');if(!b||s.done)return;const id=b.dataset.country;if(s.countrySelection.has(id))s.countrySelection.delete(id);else s.countrySelection.add(id);b.setAttribute('aria-pressed',String(s.countrySelection.has(id)))}}
else if(type){$('#heritageTypes').innerHTML=Object.entries(heritageKinds).map(([id,n])=>`<button data-kind="${id}">${n}</button>`).join('');$('#heritageTypes').onclick=e=>{const b=e.target.closest('[data-kind]');if(b)submitAnswer(false,b.dataset.kind)}}
else if(s.cfg.input==='ink')mountHandwriting();else if(s.cfg.input==='choice'){$('#choices').innerHTML=s.options.map(x=>`<button data-wh-answer="${x.id}">${esc(x.name)}</button>`).join('');$('#choices').onclick=e=>{const b=e.target.closest('[data-wh-answer]');if(b)submitAnswer(false,b.dataset.whAnswer)}}else{$('#answerForm').onsubmit=e=>{e.preventDefault();submitAnswer()};$('#answer').onkeydown=e=>{if(e.key==='Enter'&&(e.isComposing||e.keyCode===229)){e.preventDefault();e.stopPropagation()}}}}
function heritageSelect(id){const s=session;if(s.done||!s.options.some(q=>q.id===id))return;s.selected=id;heritageMapAPI.select(id);$('#selection').textContent=`候補 ${'ABCD'[s.options.findIndex(q=>q.id===id)]} を選択しました`;$('#submitLocation').disabled=false;document.querySelectorAll('[data-heritage-location]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.heritageLocation===id)))}
function heritageHint(){const s=session,q=s.queue[s.i];s.hint++;const m=s.cfg.mode;$('#hint').textContent=s.hint===1?`地域：${q.regions.join('・')}`:s.hint===2?(m==='heritageCountry'?`所在国は${q.countries.length}か国です。`:`登録上の所在国：${q.countries.map(heritageCountryName).join('・')}`):m==='heritageType'?`${q.description}`:`名前の最初：${q.reading.slice(0,1)}`;if(m==='heritageLocation'&&s.hint>=2)heritageMapAPI.focus(q)}
function heritageAccepted(q,a,m){return (m==='heritagePhoto'?q.aliases.concat(q.photoAnswers):q.aliases).some(v=>norm(v)===norm(a))}
function heritageAnswer(skip=false,choice=null){const s=session;if(!s||s.done)return;const q=s.queue[s.i],m=s.cfg.mode;let a=skip?'':m==='heritageLocation'?s.selected:m==='heritageCountry'?[...s.countrySelection].sort().join(','):choice||$('#inkText')?.value||$('#answer')?.value||'';if(!skip&&!String(a||'').trim())return;const ok=!skip&&(m==='heritageCountry'?a===[...q.countries].sort().join(','):m==='heritageType'?a===q.kind:m==='heritageLocation'||choice?a===q.id:heritageAccepted(q,a,m));s.done=true;const r=record(q,m),today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Tokyo'});r[ok?'right':'wrong']++;r.last=Date.now();r.lastRight=ok;r.streak=ok&&!s.hint?r.streak+1:0;if(ok&&!s.hint&&!r.dates.includes(today))r.dates.push(today);r.hinted=(r.hinted||0)+(s.hint?1:0);updateChannel(r,s.cfg,m,ok,s.hint,today);db.records[q.id+':'+m]=r;s.results.push({id:q.id,ok,hint:s.hint,answer:a,input:channelKey(m,s.cfg.input),mode:m,content:'heritage'});save();if(['heritageCountry','heritageType'].includes(m))$('#heritageVisual').innerHTML=heritagePhoto(q,true);$('#answerArea').hidden=true;$('#feedback').innerHTML=`<div class="${ok?'good':'bad'}"><b>${ok?'正解！':'ここで覚えよう'}</b><h2>${nameMarkup(q)}</h2><p><span class="badge">${heritageKinds[q.kind]}</span> ${q.inscribed}年登録</p><p>${esc(q.description)}</p><p>所在国：${q.countries.map(heritageCountryName).join('・')}</p>${m==='heritagePhoto'?`<p class="note">写真：${esc(q.photoSubject)}。構成資産一つと遺産全体は区別して覚えましょう。</p>${heritageCredits(q,true)}`:''}<button class="primary" onclick="next()">${s.i+1===s.queue.length?'結果を見る':'次の問題へ'} →</button><button onclick="heritageDetail('${q.id}')">図鑑で詳しく</button></div>${m==='heritagePhoto'||m==='heritageCountry'||m==='heritageType'?'<div id="feedbackHeritageMap" class="section"></div>':''}`;if(m==='heritageLocation'||m==='heritageMap')heritageMapAPI.reveal(q.id,s.selected);else mountHeritageMap($('#feedbackHeritageMap'),[q]).focus(q)}
function heritageResult(){view='result';const s=session,n=s.results.length,right=s.results.filter(r=>r.ok).length;db.history.unshift({at:Date.now(),content:'heritage',mode:s.cfg.mode,region:s.cfg.region,input:new Set(s.results.map(r=>r.input)).size>1?'mixed':s.cfg.input,scope:'all',practice:s.cfg.practice,right,n});db.history=db.history.slice(0,100);save();app.innerHTML=`<div class="setup"><span class="eyebrow">WORLD HERITAGE · COMPLETE</span><h1>世界の宝が、近くなった。</h1><section class="card"><div class="resultScore">${right}<span style="font-size:24px"> / ${n}</span></div><div class="row"><button class="primary" onclick="heritageSetup(true)">世界遺産を復習</button><button onclick="heritageSetup()">もう一度挑戦</button><button onclick="heritageAtlas()">世界遺産図鑑</button><button onclick="showResultCard()">結果画像をつくる</button><button onclick="home()">ホーム</button></div></section><div class="list section">${s.results.map(r=>{const q=heritageById(r.id);return`<button class="countryRow" onclick="heritageDetail('${q.id}')"><span>${r.ok?'○':'×'} ${esc(q.name)}<small>${heritageKinds[q.kind]} · ${r.hint?'ヒントあり':'ヒントなし'}</small></span></button>`}).join('')}</div></div>`}
function heritageAtlas(){view='heritageAtlas';app.innerHTML=`<button class="back" onclick="home()">← ホーム</button><span class="eyebrow">WORLD HERITAGE ATLAS</span><h1>世界の宝を、見つけよう。</h1><div class="fields card"><div><label for="whSearch">名前・国で検索</label><input id="whSearch" placeholder="京都 / エジプト / Machu Picchu"></div><div><label for="whKind">種類</label><select id="whKind"><option value="all">すべて</option>${Object.entries(heritageKinds).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div><label for="whRegion">地域</label><select id="whRegion"><option>世界全体</option>${REGIONS.map(r=>`<option>${r}</option>`).join('')}</select></div><div><label for="whState">学習状態</label><select id="whState"><option value="all">すべて</option><option value="new">未挑戦</option><option value="review">復習したい</option><option value="master">マスターあり</option></select></div></div><p id="whCount" class="note section"></p><div id="whList" class="heritageGrid"></div>`;['whSearch','whKind','whRegion','whState'].forEach(id=>$('#'+id).oninput=renderHeritageAtlas);renderHeritageAtlas()}
function renderHeritageAtlas(){const needle=norm($('#whSearch').value),kind=$('#whKind').value,reg=$('#whRegion').value,state=$('#whState').value;const found=heritage.filter(q=>(kind==='all'||q.kind===kind)&&(reg==='世界全体'||q.regions.includes(reg))&&q.aliases.concat(q.photoAnswers,q.countries.map(heritageCountryName)).some(n=>norm(n).includes(needle))).map(q=>{const rs=Object.keys(heritageModes).map(m=>record(q,m)),n=rs.reduce((a,r)=>a+r.right+r.wrong,0),cs=rs.flatMap(r=>Object.values(r.channels||{}));return{q,n,review:cs.some(r=>r.wrong&&!r.lastRight),master:cs.some(r=>statusOf(r)==='マスター')}}).filter(r=>state==='all'||state==='new'&&!r.n||state==='review'&&r.review||state==='master'&&r.master);$('#whCount').textContent=`${found.length}件／全${heritage.length}件の代表例`;$('#whList').innerHTML=found.map(({q,n,review,master})=>`<article class="heritageTile"><button class="heritageTileButton" onclick="heritageDetail('${q.id}')">${q.photo?`<img loading="lazy" src="${q.photo.path}" alt="${esc(q.photoSubject)}">`:`<div class="photoPlaceholder">地図で学ぶ</div>`}<div><span class="tag">${heritageKinds[q.kind]}</span><h3>${esc(q.name)}</h3><p class="note">${q.countries.map(heritageCountryName).join('・')}<br>${master?'マスターあり':review?'復習したい':n?'練習中':'未挑戦'} · ${n}回学習</p></div></button>${heritageCredits(q)}</article>`).join('')||'<p>この条件の世界遺産はありません。</p>'}
function heritageDetail(id){const q=heritageById(id);if(!q)return;showModal(`<span class="eyebrow">WORLD HERITAGE · ${heritageKinds[q.kind]}</span><h2>${nameMarkup(q)}</h2>${heritagePhoto(q,true)}<p>${esc(q.description)}</p><p>所在国：${q.countries.map(heritageCountryName).join('・')}<br>${q.inscribed}年登録${q.secondaryDates?' · 拡張など：'+q.secondaryDates:''}</p><div id="heritageDetailMap"></div><p class="note">掲載地点：${q.positions.length}地点${q.transnational?' · 複数国の登録遺産':''}<br>${q.accuracy}</p><div class="skillGrid">${Object.entries(heritageModes).map(([m,n])=>{const r=record(q,m);return`<div class="skill"><b>${n}</b><p>${r.right}正解 / ${r.wrong}不正解</p>${skillDetails(r,m)}</div>`}).join('')}</div><div class="row section"><button class="primary" onclick="document.querySelector('#modal').close();heritageStart({ids:['${id}'],mode:'${q.photo?'heritagePhoto':'heritageMap'}',count:1})">${q.photo?'写真':'地図'}を練習</button><button onclick="document.querySelector('#modal').close();heritageStart({ids:['${id}'],mode:'heritageLocation',count:1})">位置を練習</button></div><details><summary>登録名・出典・回答の扱い</summary><p>${esc(q.en)}</p><p class="note">${q.scopeNote}<br><a href="${q.source}" target="_blank" rel="noopener">UNESCO World Heritage Centre · ${q.unescoId}</a><br>確認日：${q.checked}。点は位置の目安で、登録範囲の境界ではありません。</p></details>`);mountHeritageMap($('#heritageDetailMap'),[q]).focus(q)}
function heritageSources(){showModal(`<h2>世界遺産の情報と写真</h2><p>登録名・種類・登録年・所在国・掲載地点は、<a href="https://whc.unesco.org/en/list/" target="_blank" rel="noopener">UNESCO World Heritage Centre</a>で確認しています。確認日：2026年10月16日。本ゲームはUNESCOの公式教材ではありません。</p><p>収録は${heritage.length}件の代表例です。地図は掲載地点を示し、登録範囲の面積や境界は再現していません。登録名の日本語は学習用に略記する場合があります。</p><p>写真はWikimedia Commonsで公開され、再利用条件を確認した実写です。撮影者・出典・ライセンスは各図鑑ページで表示しています。生成画像は使用していません。</p><p><a href="licenses/heritage-photo-credits.json" target="_blank" rel="noopener">全写真のクレジット一覧</a></p><div class="scrollList">${heritage.filter(q=>q.photo).map(q=>`<p><b>${esc(q.name)}</b><br><a href="${q.source}" target="_blank" rel="noopener">登録情報</a> · <a href="${q.photo.sourcePage}" target="_blank" rel="noopener">写真出典</a> · ${esc(q.photo.author)} · <a href="${q.photo.licenseUrl}" target="_blank" rel="noopener">${esc(q.photo.license)}</a></p>`).join('')}</div>`)}
function mixedSetup(){view='mixedSetup';app.innerHTML=`<div class="setup"><button class="back" onclick="home()">← ホーム</button><span class="eyebrow">WORLD TOUR CHALLENGE</span><h1>知っている世界を、つなげよう。</h1><form id="mixedSetup" class="card"><label>出題する分野</label><div class="checks"><label><input type="checkbox" name="mixedGroup" value="country" checked>国・国旗</label><label><input type="checkbox" name="mixedGroup" value="terrain" checked>地形</label><label><input type="checkbox" name="mixedGroup" value="heritage" checked>世界遺産</label></div><div class="fields"><div><label for="mixedInput">名前の回答方法</label><select id="mixedInput"><option value="choice">4択</option><option value="text">キーボード入力</option><option value="ink">かな手書き（ベータ）</option></select></div><div><label for="mixedCount">問題数</label><select id="mixedCount"><option>10</option><option>20</option><option>30</option></select></div><div><label for="mixedRegion">地域</label><select id="mixedRegion"><option>世界全体</option>${REGIONS.map(r=>`<option>${r}</option>`).join('')}</select></div><div><label for="mixedScope">国・国旗の出題範囲</label><select id="mixedScope">${scopeOptions()}</select></div></div><p class="note">名前・位置・世界遺産の国や分類を組み合わせます。ヒントなしのテスト形式です。正解数で自己ベストを記録し、条件が違う記録とは分けて比べます。</p><button class="primary" type="submit">世界一周チャレンジ →</button><p id="setupMsg" aria-live="polite"></p></form></div>`;$('#mixedSetup').onsubmit=e=>{e.preventDefault();mixedStart({groups:[...document.querySelectorAll('[name=mixedGroup]:checked')].map(x=>x.value),input:$('#mixedInput').value,count:+$('#mixedCount').value,region:$('#mixedRegion').value,scope:$('#mixedScope').value})}}
function mixedStart(options={}){const cfg={groups:['country','terrain','heritage'],input:'choice',count:10,region:'世界全体',scope:'basic',...options};cfg.groups=[...new Set(cfg.groups)].filter(x=>['country','terrain','heritage'].includes(x));if(!cfg.groups.length){if($('#setupMsg'))$('#setupMsg').textContent='出題する分野を一つ以上選んでください。';return false}cfg.count=Math.max(1,Math.min(30,Math.floor(+cfg.count)||10));const pools={country:shuffle(data.filter(q=>inScope(q,cfg.scope)&&(cfg.region==='世界全体'||q.region===cfg.region))),terrain:shuffle(terrain.filter(q=>cfg.region==='世界全体'||q.regions.includes(cfg.region))),heritage:shuffle(heritage.filter(q=>cfg.region==='世界全体'||q.regions.includes(cfg.region)))};let queue=[],indices={country:0,terrain:0,heritage:0};while(queue.length<cfg.count){let added=false;for(const content of cfg.groups){const q=pools[content].pop();if(!q)continue;const ix=indices[content]++,modes=content==='country'?['flag','name','location']:content==='terrain'?['terrainName','terrainLocation']:['heritagePhoto','heritageLocation','heritageCountry','heritageType','heritageMap'],mode=modes[ix%modes.length],input=['heritageCountry','heritageType'].includes(mode)?'choice':cfg.input;queue.push({...q,task:{content,mode,input,scope:cfg.scope,region:cfg.region,practice:'test'}});added=true;if(queue.length>=cfg.count)break}if(!added)break}if(!queue.length){if($('#setupMsg'))$('#setupMsg').textContent='この地域・分野の問題はありません。';return false}const key=JSON.stringify({v:1,groups:[...cfg.groups].sort(),input:cfg.input,count:cfg.count,region:cfg.region,scope:cfg.scope});session={mixed:true,challengeOptions:cfg,challengeKey:key,cfg:{practice:'test'},queue,i:0,results:[],began:Date.now(),done:false,hint:0};question();return true}
function itemForResult(r){return r.content==='heritage'?heritageById(r.id):r.content==='terrain'?terrainById(r.id):data.find(c=>c.id===r.id)}
function resultDetail(id,content){if(content==='heritage')heritageDetail(id);else if(content==='terrain')terrainDetail(id);else country(id)}
function mixedResult(){view='result';const s=session,n=s.results.length,right=s.results.filter(r=>r.ok).length,c=s.challengeOptions,prior=db.history.filter(h=>h.mode==='mixed'&&h.challengeKey===s.challengeKey&&!h.inputChanged&&h.n===n),best=Math.max(right,...prior.map(h=>h.right)),elapsed=Math.max(0,Date.now()-s.began);db.history.unshift({at:Date.now(),content:'mixed',mode:'mixed',input:'mixed',region:c.region,scope:c.scope,practice:'test',right,n,challengeKey:s.challengeKey,inputChanged:!!s.inputChanged,durationMs:elapsed});db.history=db.history.slice(0,100);save();const names={country:'国・国旗',terrain:'地形',heritage:'世界遺産'};app.innerHTML=`<div class="setup"><span class="eyebrow">WORLD TOUR · COMPLETE</span><h1>${right===n?'世界一周、全問正解！':'世界の知識が、つながった。'}</h1><section class="card"><div class="resultScore">${right}<span style="font-size:24px"> / ${n}</span></div><p>${s.inputChanged?'入力方法を切り替えたため、自己ベスト比較の対象外です。':`同じ条件の自己ベスト：${best} / ${n}${!prior.length?'（今回が初挑戦）':''}`}</p><p class="note">${c.groups.map(k=>names[k]).join('・')} / ${c.region} / 名前は${inputLabel('name',c.input)}<br>所要時間 ${Math.floor(elapsed/60000)}分${Math.floor(elapsed/1000)%60}秒。時間は得点に影響しません。</p><div class="row"><button class="primary" onclick="showResultCard()">結果画像をつくる</button><button onclick="mixedSetup()">もう一度挑戦</button><button onclick="home()">ホーム</button></div></section><div class="cards section">${c.groups.map(content=>{const rs=s.results.filter(r=>r.content===content);return`<div class="card"><h3>${names[content]}</h3><strong>${rs.filter(r=>r.ok).length} / ${rs.length}</strong></div>`}).join('')}</div><div class="list section">${s.results.map(r=>{const q=itemForResult(r);return`<button class="countryRow" onclick="resultDetail('${r.id}','${r.content}')"><span>${r.ok?'○':'×'} ${esc(q.name)}<small>${names[r.content]}</small></span></button>`}).join('')}</div></div>`}
let shareCardFile=null,shareCardUrl=null;
function resultCardSummary(){if(!session||view!=='result')return null;const s=session;return{title:s.mixed?'世界一周チャレンジ':s.cfg.content==='heritage'?'世界遺産マスター':s.cfg.content==='terrain'?'世界の地形マスター':'国・国旗マスター',right:s.results.filter(r=>r.ok).length,n:s.results.length,region:s.mixed?s.challengeOptions.region:s.cfg.region||'世界全体',method:s.mixed?'名前：'+inputLabel('name',s.challengeOptions.input)+(s.inputChanged?'（入力切替あり）':''):inputLabel(s.cfg.mode,s.cfg.input),practice:s.cfg.practice==='test'||s.mixed?'ヒントなしテスト':'練習',date:new Date().toLocaleDateString('ja-JP'),groups:['country','terrain','heritage'].map(k=>({label:{country:'国・国旗',terrain:'地形',heritage:'世界遺産'}[k],n:s.results.filter(r=>(r.content||'country')===k).length,right:s.results.filter(r=>(r.content||'country')===k&&r.ok).length})).filter(r=>r.n)}}
async function showResultCard(){const info=resultCardSummary();if(!info)return;try{if(document.fonts?.load)await document.fonts.load('bold 45px WorldMasterShare');const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=630;const ctx=canvas.getContext('2d');if(!ctx)throw Error('canvas');ctx.fillStyle='#f3f5eb';ctx.fillRect(0,0,1200,630);ctx.fillStyle='#176d60';ctx.fillRect(0,0,1200,18);ctx.fillStyle='#e4edcf';ctx.beginPath();ctx.arc(1080,120,250,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c3d4ad';ctx.lineWidth=2;for(let i=0;i<4;i++){ctx.beginPath();ctx.ellipse(1060,140,90+i*40,180,0,0,Math.PI*2);ctx.stroke()}ctx.fillStyle='#176d60';ctx.font='bold 25px WorldMasterShare,system-ui,sans-serif';ctx.fillText('WORLD MASTER',64,79);ctx.fillStyle='#183f3b';ctx.font='bold 45px WorldMasterShare,system-ui,sans-serif';ctx.fillText(info.title,64,158);ctx.font='bold 145px WorldMasterShare,system-ui,sans-serif';ctx.fillText(String(info.right),64,330);const scoreWidth=ctx.measureText(String(info.right)).width;ctx.font='bold 48px WorldMasterShare,system-ui,sans-serif';ctx.fillText('/ '+info.n+' 問',96+scoreWidth,325);ctx.font='27px WorldMasterShare,system-ui,sans-serif';ctx.fillText(`${info.region} · ${info.practice}`,64,395);ctx.font='23px WorldMasterShare,system-ui,sans-serif';ctx.fillText(info.method,64,439);ctx.fillText(info.groups.map(g=>`${g.label} ${g.right}/${g.n}`).join('   '),64,491);ctx.fillStyle='#647a6e';ctx.font='21px WorldMasterShare,system-ui,sans-serif';ctx.fillText('地図の向こうに、まだ知らない世界。',64,570);ctx.fillText(info.date,980,570);const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('blob')),'image/png'));shareCardFile=typeof File==='function'?new File([blob],'world-master-result.png',{type:'image/png'}):blob;if(shareCardUrl)URL.revokeObjectURL(shareCardUrl);shareCardUrl=URL.createObjectURL(blob);showModal(`<h2>世界マスターの結果画像</h2><img class="resultCardPreview" src="${shareCardUrl}" alt="${esc(info.title)} ${info.right}/${info.n}問正解"><div class="row section"><a class="downloadButton" href="${shareCardUrl}" download="world-master-result.png">画像を保存</a><button class="primary" id="shareCardButton">共有する</button></div><p class="note">保存できない場合は、画像を長押しして保存してください。共有先は端末の画面で選べます。</p>`);$('#shareCardButton').onclick=shareResultCard}catch(e){showModal('<h2>結果画像を作れませんでした</h2><p>このブラウザでは画像出力を利用できません。結果画面のスクリーンショットをご利用ください。</p>')}}
async function shareResultCard(){try{if(shareCardFile&&navigator.canShare?.({files:[shareCardFile]})){await navigator.share({files:[shareCardFile],title:'世界マスターの学習結果'})}else{const p=document.createElement('p');p.className='note';p.textContent='このブラウザではファイル共有を利用できません。「画像を保存」または画像の長押しをご利用ください。';$('#modalBody').append(p)}}catch(e){if(e.name!=='AbortError'){const p=document.createElement('p');p.className='note';p.textContent='共有を完了できませんでした。画像を保存してご利用ください。';$('#modalBody').append(p)}}}

$('#brand').onclick=e=>{e.preventDefault();if(view==='game'&&!session?.done)leave();else home()};
async function boot(){try{const rs=await Promise.all([fetch('assets/data.json'),fetch('assets/map.json'),fetch('assets/terrain.json'),fetch('assets/heritage.json')]);if(rs.some(r=>!r.ok))throw Error('地図データを取得できませんでした');[data,geo,terrain,heritage]=await Promise.all(rs.map(r=>r.json()));home()}catch(e){app.innerHTML='<section class="card"><h2>読み込みを完了できませんでした</h2><p>通信状態を確認して、もう一度お試しください。</p><button onclick="boot()">再試行</button></section>'}}
// boot is invoked after expansion.js loads.

function retryHeritagePhoto(button){const figure=button.closest('figure'),img=figure?.querySelector('img'),error=figure?.querySelector('.photoError');if(!img||!error)return;error.hidden=true;img.hidden=false;img.src=img.src.split('?')[0]+'?retry='+Date.now()}
